\title{Systolic inequalities on the sphere from symplectic embeddings}
\date{}
\author{Brayan Ferreira}

\begin{document}
\maketitle

\begin{abstract}
We use properties of symplectic capacities that were recently defined by Hutchings to obtain upper bounds on the minimal action of Reeb orbits on fiberwise star-shaped hypersurfaces $\Sigma \subset T^*S^2$. In addition, we introduce the notion of a fiberwise $\beta$-balanced hypersurface $\Sigma \subset T^*S^2$ and establish upper bounds for the systole in terms of $\beta$ and geometric data, in the case of Riemannian metrics on $S^2$ satisfying this property. Finally, under the assumption of antipodal symmetry, we provide a non-sharp estimate of how fiberwise balanced a $\delta$-pinched metric is.
\end{abstract}

\tableofcontents

\section{Introduction}
Let $(Y,\lambda)$ be a contact three-dimensional manifold, i.e., $\lambda$ is a $1$-form such that $\lambda \wedge d\lambda \neq 0$. The \emph{Reeb vector field} is defined as the unique vector field $R$ satisfying the equations $d\lambda(R,\cdot) = 0$ and $\lambda(R) = 1$ on $Y$.
The famous Weinstein conjecture says that the Reeb flow on a closed contact manifold always admits a periodic trajectory. The conjecture is proved in dimension $3$ by Taubes \cite{taubes2007seiberg}. Given a periodic Reeb orbit $\gamma \colon \R/T\Z \to Y$, we define its action by
$$\mathcal{A}_\lambda(\gamma) = \int_\gamma \lambda = T.$$
The aim of this paper is to obtain upper bounds on the minimal action
$$\mathcal{A}_{min}(Y,\lambda) := \min\{ \mathcal{A}_\lambda(\gamma) \vert \ \gamma \ \text{periodic Reeb orbit on} \ Y\},$$
for specific contact closed three-dimensional manifolds in the cotangent bundle of the two-dimensional sphere, $T^*S^2$. In what follows, we denote by $S^2 \subset \R^3$ the unit sphere and by $g_0$ the round metric inherited from the Euclidean space.

In \cite{hutchings2022elementary}, Hutchings defined a sequence 

$$ 0 = c_0(X,\omega) \leq c_1(X,\omega) \leq c_2(X,\omega) \leq \ldots \leq +\infty$$
of numerical invariants (symplectic capacities) for any four dimensional symplectic manifold $(X,\omega)$. These numbers are defined as minimax values of energies of suitable pseudoholomorphic curves with point constraints and satisfy nice properties. We recall those we shall use in this work.

\begin{theorem}[{\cite[Theorem 6]{hutchings2022elementary}}]\label{ckprop}
The numbers $c_k$ satisfy the following properties:
\begin{enumerate}
\item (Conformality) $c_k(X,r \omega) = r c_k(X,\omega)$ for any $r>0$.
\item (Monotonicity) If there exists a symplectic embedding $(X_1,\omega_1) \hookrightarrow (X_2,\omega_2)$, then $c_k(X_1,\omega_1) \leq c_k(X_2,\omega_2)$.
\item (Spectrality) If $(X,\omega)$ is a four-dimensional Liouville domain with boundary $Y$, then for each $k$ such that $c_k(X,\omega)<\infty$, there exists an orbit set $\alpha=\{(\gamma_i,m_i)\}$ in $Y$ with $c_k(X,\omega) = \mathcal{A}(\alpha) = \sum_i m_i \mathcal{A}_\lambda(\gamma_i)$.
\item (Ball) The numbers $c_k$ for the \emph{ball of capacity $a$},
$$B(a) = \{x \in \R^4 \mid \pi \Vert x \Vert^2 \leq a\},$$
are given by $c_k(B(a),\omega_0) = da$, where $d$ is the unique nonnegative integer with
$$d^2+d \leq 2k \leq d^2+3d.$$
Here $\omega_0 = dx_i \wedge dy_i$ denotes the standard symplectic form on $\R^4$. In particular, $c_1(B(a),\omega_0) = a$.
\item (Round metric) The numbers $c_k$ for the unit disk cotangent bundle $D^*_{g_0}(1)S^2$ are given by
$$c_k(D^*_{g_0}(1)S^2,\omega_{can}) = \min \{2\pi(m+n) \mid m,n \in \mathbb{N}, \ (m+1)(n+1) \geq k+1\},$$
where $\omega_{can}$ denotes the canonical symplectic form on the cotangent bundle $T^*S^2$. In particular, $c_1(D_{g_0}^*(1)S^2,\omega_{can}) = 2\pi$.
\end{enumerate}
\end{theorem}

As mentioned in \cite[Remark 14]{hutchings2022elementary}, it follows from \cite[Theorem 1.1]{ferreira2021symplectic} and \cite[Lemma 2.3]{oakleyusher} that there exist symplectic embeddings
$$(\mathrm{int} P(2\pi,2\pi),\omega_0) \hookrightarrow (D_{g_0}^*(1)S^2,\omega_{can}) \hookrightarrow (S^2 \times S^2, \sigma(2\pi) \oplus \sigma(2\pi)),$$
where $P(a,b)$ is the symplectic polydisk
$$P(a,b) =\{(z_1,z_2) \in \C^2 \mid \pi \vert z_1 \vert^2 \leq a, \  \vert z_2 \vert^2 \leq b\},$$
$\omega_0$ is the standard symplectic form on $\R^4 = \C^2$ and $\sigma(A)$ is the area form on $S^2$ such that $\int_{S^2} \sigma(A) = A$.

Therefore, by the monotonicity property, we have 
$$c_k(\mathrm{int} P(2\pi,2\pi),\omega_0)\leq c_k(D_{g_0}^*(1)S^2,\omega_{can}) \leq c_k(S^2 \times S^2, \sigma(2\pi) \oplus \sigma(2\pi)),$$
for every $k$. The round metric property in Theorem \ref{ckprop} follows from Hutchings' computations for the polydisks $P(a,b)$ and $S^2 \times S^2$, see \cite[Theorem 17]{hutchings2022elementary}.

Before we state the first result of this work, we recall that given a Riemannian (or more generally, Finsler) metric on a manifold $N$, say $g$, one has Liouville domains associated to it inside the cotangent bundle $T^*N$. In fact, for each $r>0$, we define the \emph{disk cotangent bundle of radius $r$ with respect to $g$} as being the manifold
$$D^*_g(r)N = \{\nu \in T^*N \mid \sqrt{g^*(\nu,\nu)}\leq r\}.$$
Here $g^*$ denotes the dual metric defined by $g$, that is, we have
$$g^*(\nu_1,\nu_2) = g((g^b)^{-1}(\nu_1),(g^b)^{-1}(\nu_2)),$$
where $g^b$ is the vector bundle isomorphism
\begin{align*}
g^b \colon TN &\to T^*N \\ u &\mapsto g(u,\cdot).
\end{align*}
More generally, one can consider a Finsler metric $F\colon TN \to [0,+\infty)$ and define
$$D_F^*(r)N = \{\nu \in T^*N \mid F^*(\nu)\leq r\},$$
where $F^*$ is the (co)-Finsler (or Cartan) metric $F^* \colon T^*N \to \R$ defined by $F^*(\nu) = F(\mathcal{L}^{-1}(\nu))$, where $\mathcal{L}\colon TN \to T^*N$ is the Legendre transform. In this case, it is well known that the canonical symplectic form
$$\omega_{can} = \sum_i dp_i \wedge dq_i$$
restricts to a symplectic structure on $D^*_F(r)N$ such that the boundary
$$\partial D^*_F(r)N = S^*_F(r)N = \{\nu \in T^*N \mid F^*(\nu) = r\}$$
is a contact manifold equipped with the tautological one form
$$\lambda = \sum_i p_idq_i.$$
Moreover, the Reeb flow associated with $\lambda$ coincides with the (co)-geodesic flow for $F$. In particular, the Reeb trajectories are given by $\mathcal{L}(\gamma, \dot{\gamma})$, where $\gamma$ is a geodesic on $N$ such that $F(\gamma) = r$. Also, the action as a Reeb orbit $\mathcal{A}_{\lambda}(\mathcal{L}(\gamma,\dot{\gamma}))$ coincides with the length of the geodesic $L(\gamma) = \int F(\gamma,\dot{\gamma})$. For these facts and more connections between Contact Topology and Finsler Geometry, we recommend \cite{hryniewicz2013introduccao,dorner2017finsler} or also \cite[Appendix B.1.]{abbondandolo2023entropy}.

Our first result follows from the properties listed in Theorem \ref{ckprop}.

\begin{theorem}\label{systolicineq}
Let $(X,\omega)$ be a four-dimensional Liouville domain with boundary being a contact manifold $(Y,\lambda)$. Suppose that there exists a symplectic embedding $(X,\omega) \hookrightarrow (D^*_{g_0}(R)S^2,\omega_{can})$. Then, we have the inequality
$$\mathcal{A}_{min}(Y,\lambda) \leq 2\pi R.$$
\end{theorem}
\begin{proof}
If such an embedding exists, the monotonicity property yields
$$c_1(X_,\omega) \leq c_1(D^*_{g_0}(R)S^2,\omega_{can}).$$
In addition,
$$c_1(D^*(R)S^2,\omega_{can}) = c_1(D^*(1)S^2,R\omega_{can}) = 2\pi R,$$
by the conformality property. The desired inequality follows from the spectrality property, which ensures that $\mathcal{A}_{min}(Y,\lambda) \leq c_1(X,\omega)$.
\end{proof}

On the other hand, one can also study symplectic embeddings in the opposite direction. The monotonicity of $c_k$ yields
\begin{equation}\label{lowerboundc1}
2\pi r = c_1(D_{g_0}^*(r)S^2,\omega_{can}) \leq c_1(X,\omega),
\end{equation}
whenever a symplectic embedding $ (D_{g_0}^*(r)S^2,\omega_{can}) \hookrightarrow (X,\omega)$ exists. Since it is not always true that $c_1(X,\omega)$ coincides with the minimal action of Reeb orbits on the boundary of $X$, we do not recover the opposite direction in Theorem \ref{systolicineq} in general.

