  \includegraphics{Grafico_Special}
}}
\end{center}
\caption{\label{fig:three}\Nv\footnotesize Graph of the special-$[\frac{1}{10},2,0 ]$-defined function.}
\end{figure}

\Fig{fig:three} charts the special-$[\frac{1}{10},2,0 ]$-defined function.

\medskip


The previous definition of middle slope naturally generalizes to a special-$[\al ,{\theta}_1, {\theta}_2]$-defined function: referring to the definition of such just made, this will be the middle slope of $C_2(x)$, i.e., $\theta \in \mR $ with $\abs{\theta}=\abs{4\al}$.\\
A special-$[\al , {\theta}_1, {\theta}_2]$-defined function is continuous and differentiable (with a continuous derivative) in $[0,1]$; we also have $C'(0)={\theta}_1,\ C'(1)={\theta}_2$ and $C'(\frac{1}{2})\! =\! \theta$. Moreover, $C(x)$ is the null function if and only if $\al ={\theta}_1 ={\theta}_2 =0$. 

As before, we have the following existence conditions:
\begin{lemma}\label{lem:1.5}
Let $\al ,{\theta}_1 ,{\theta}_2
$ be real numbers, with ${\theta}_1 \x {\theta}_2=0$. A special-$[\al ,{\theta}_1, {\theta}_2]$-defined function exists if and only if either of the following holds:
\begin{itemize}
\item $\al ={\theta}_1 = {\theta}_2 =0$,

\item $0<|4\al|\leq |{\theta}_1+{\theta}_2|$.
\end{itemize}
Moreover, when the function at issue exists it is unique.
\end{lemma}
\dimostraz  If $\al ={\theta}_1 ={\theta}_2 =0$, the claim is trivial.\\
Otherwise, let $0 \! < \! |4\al | \! \leq \! |{\theta}_1 +{\theta}_2 |$ and, without loss of generality, let us suppose that ${\theta}_1 =0\not= {\theta}_2$ and that $C_1(x)$ is the everywhere null function on $[0,1]$.
By \Lem{lem:1.3}, a double-$[\al ,{\theta}_1, {\theta}_2 ]$-defined function $C_2(x)$ exists, as ${\theta}_2 \x {\theta}_2 >0$ and $0<|4\al |\leq |{\theta}_2|$ hold by hypothesis.
Moreover, by \Lem{lem:1.1}, a single-$[\al ,-{\theta}_2 , {\theta}_2 ]$-defined function $C_3(x)$ exists, as $-{\theta}_2 \x {\theta}_2 <0 $ and $0<|4\al |\leq |{\theta}_2|$ hold.
Thus, the function $C(x)$ obtained as by \Def{def:1.5} from $C_1 ,C_2 ,C_3$ is a special-$[\al ,{\theta}_1 ,{\theta}_2 ]$-defined.
The converse implication can be obtained coming back through the proof. \qed 

As for single- and double-defined function, we have the following result about the derivative of a special-$[\al ,{\theta}_1, {\theta}_2]$-defined function:
\begin{lemma} 
Let $k\in \mR$ and let $C(x)$ be a special-$[\al, {\theta}_1, {\theta}_2]$-defined function, with $\theta \in \mR$ its middle slope. If ${\theta}_1,{\theta}_2, \theta \bowtie k$ (where ${\bowtie} \in \{\leq, <, >, \geq \}$), then $C'(x) \bowtie k$ for all $x\in [0,1]$. 
\end{lemma}
\dimostraz Let $C_1, C_2 ,C_3$ be the components of the function $C(x)$ as defined in \Def{def:1.5}. We have:
\[
C'(x)= 
\begin{cases}
C_1'(p(x))\x p'(x) & \text{if }\ x\in [ 0, \frac{1}{4} ] , \\[0.1cm]
C_2'(x) & \text{if}\ x\in \, ] \frac{1}{4}, \frac{3}{4} ] , \\[0.1cm]
C_3'(q(x))\x q'(x) & \text{if }\ x\in \, ] \frac{3}{4}, 1 ] .
\end{cases}
\]
It is easy to check that $C'(x)>k$ is true for all $x\in [0,1]$. \qed 


We can now combine the definitions given above to obtain:
\begin{definition} A real function $C \colon   [0,1]\frec \mR $ is said to be \textsc{$[\al, {\theta}_1, {\theta}_2]$-defined}  if and only if it is either single-$[\al, {\theta}_1, {\theta}_2]$-defined, double-$[\al, {\theta}_1, {\theta}_2]$-defined or special-$[\al, {\theta}_1, {\theta}_2]$-defined.
\end{definition}


An $[\al, {\theta}_1, {\theta}_2]$-defined  function $C(x)$ is continuous and differentiable (with a continuous derivative) in $[0,1]$. We also have $C'(0)={\theta}_1$, $C'(1)={\theta}_2$ and
\[
\textstyle \abs{C'\left (\frac{1}{2}\right)} =
    \left\{
    \begin{array}{ll}
    0 & \mbox{if}\ C(x)\ \mbox{is}\ \mbox{single-}[\al ,{\theta}_1, {\theta}_2]\mbox{-defined}, \\[0.1cm]
    |4\al| & \mbox{otherwise}.
    \end{array}
    \right.
\]
Moreover, $C(x)$ is the null function in $[0,1]$ if and only if ${\theta}_1 \! = \! {\theta}_2 \! =0$.

\begin{lemma}\label{lem:1.7}
Let $\al, {\theta}_1, {\theta}_2$ be real numbers and let $C(x)$ be an $[\al, {\theta}_1, {\theta}_2]$-defined function; then,$|C(x)|\leq |\al|$ holds for all $x\in [0,1]$.
\end{lemma}
\dimostraz Straightforward from the definitions given before. \qed 

Even for an $[\al, {\theta}_1, {\theta}_2]$-defined function there are existence conditions:
\begin{lemma}\label{lem:1.8} Let $\al ,{\theta}_1, {\theta}_2$ be real numbers. An $[\al, {\theta}_1, {\theta}_2]$-defined function exists if and only if either of the following holds:
\begin{itemize}
\item $\al={\theta}_1 \! =\! {\theta}_2 \! =0$,

\item $0<|4\al|\leq \min \{ |x| \,|\, x\not= 0\ \mbox{and}\ x \in \{ {\theta}_1,{\theta}_2 \} \}$.
\end{itemize}
Moreover, when the function at issue exists it is unique.
\end{lemma}
\dimostraz Straightforward by Lemmas \ref{lem:1.1}, \ref{lem:1.3} and \ref{lem:1.5}. \qed 

\begin{corollary}\label{cor:1.3} Let $\al ,{\theta}_1, {\theta}_2, {\theta}_3, {\theta}_4$ be real numbers, and let $C_1(x),\ C_2(x)$ be, respectively, an $[\al ,{\theta}_1 ,{\theta}_2]$-defined function and an $[\al ,{\theta}_3, {\theta}_4]$-defined function. Then $C_1(x)\! =\! C_2(x)$ for all $x\! \in \! [0,1]$ if and only if ${\theta}_1 ={\theta}_3$ and ${\theta}_2 = {\theta}_4$.
\end{corollary}
\dimostraz Straightforward by the above lemma. \qed 

We now prove some other properties for $[\al ,{\theta}_1, {\theta}_2]$-defined functions that will be used in the next chapter.

\begin{lemma}\label{lem:1.9} Let $f$ be a single-$[\al ,{\theta}_1, {\theta}_2 ] $-defined function and $\be \! \in \! \mR $ such that $|\al | \! > \! |\be |$, then we have $|f| \! \geq \! |g|$ in $[0,1]$ with $g$  single-$[\be, {\theta}_1, {\theta}_2 ]$-defined function.
\end{lemma}
\dimostraz First we suppose $\al \! > \!  \be \! > \! 0$. Since $f$ and $g$ are single-defined, we can analyze separately the two intervals $[0, \frac{1}{2}]$ and $[\frac{1}{2},1]$. Let us consider the first one. The fact that $f$ and $g$ are single-defined yields:
\[
\textstyle f(x)=\al [1-(2x-1)^2 e^{-2d_{\al}x}]\ \nor{with}\ d_{\al}=\frac{{\theta}_1}{2 \al}-2\ \nor{in}\  \left[ 0,\frac{1}{2} \right]
\]
and
\[
\textstyle g(x)=\be [1-(2x-1)^2 e^{-2d_{\be}x}]\ \nor{with}\ d_{\be}=\frac{{\theta}_1}{2 \be}-2\ \nor{in}\ \left[ 0,\frac{1}{2} \right].
\]
Since $\al >\be >0$, we can consider $\be = \frac{\al}{c}$ with $c>1$, so:
\[
\textstyle f(x)=\al \left[1-(2x-1)^2 e^{-2\left( \frac{{\theta}_1}{2 \al}-2 \right) x} \right]\  \nor{in}\  \left[ 0,\frac{1}{2} \right]
\]
and
\[
\textstyle g(x)=\frac{\al}{c} \left[ 1-(2x-1)^2 e^{-2 \left( \frac{{\theta}_1}{2 \left( \frac{\al}{c} \right)}-2 \right) x} \right]\  \nor{in}\ \left[ 0,\frac{1}{2} \right].
\]
For the sake of simplicity, we replace $\frac{{\theta}_1}{\al}$ by $A$ (with $A>0$), and since $\al < \frac{{\theta}_1}{4}$ (by the definition of a single-defined function), we also have $A>4$. \\ In order to prove that:
\[
\textstyle \al \left[1-(2x-1)^2 e^{-2\left( \frac{A}{2}-2 \right) x} \right] \geq \frac{\al}{c} \left[ 1-(2x-1)^2 e^{-2 \left( \frac{cA}{2}-2 \right) x} \right]\  \nor{in}\ \left[ 0,\frac{1}{2} \right] ,
\]
we argue as follows:
\begin{align*}
~~~~~~~~~~~~~~~~~~ & \textstyle \hspace{-2cm}\al \left[1-(2x-1)^2 e^{-2\left( \frac{A}{2}-2 \right) x}  \right] \geq \frac{\al}{c} \left[ 1-(2x-1)^2 e^{-2 \left( \frac{cA}{2}-2 \right) x} \right]\  \nor{in}\ \left[ 0,\frac{1}{2} \right] \\ 
&\textstyle ~~\Longleftrightarrow ~~
c \left[1-(2x-1)^2 e^{(-A+4)x} \right] \geq  \left[ 1-(2x-1)^2 e^{(-cA+4)x} \right]\  \nor{in}\ \left[ 0,\frac{1}{2} \right] \\
&\textstyle ~~\Longleftrightarrow ~~c-c(2x-1)^2e^{-Ax+4x}\ \geq 1-(2x-1)^2 e^{-cAx+4x}\ \nor{in}\ \left[ 0,\frac{1}{2} \right] \\
&\textstyle ~~\Longleftrightarrow ~~c-1\ \geq c(2x-1)^2e^{-Ax+4x}-(2x-1)^2 e^{-cAx+4x}\ \nor{in}\ \left[ 0,\frac{1}{2} \right] \\
&\textstyle ~~\Longleftrightarrow ~~ c-1\ \geq c(2x-1)^2e^{-Ax}e^{4x}-(2x-1)^2 e^{-cAx}e^{4x}\ \nor{in}\ \left[ 0,\frac{1}{2} \right] \\
&\textstyle ~~\Longleftrightarrow ~~ c-1\ \geq (2x-1)^2e^{4x}[ce^{-Ax}-e^{-cAx}]\ \nor{in}\ \left[ 0,\frac{1}{2} \right].
\end{align*}
So, let us consider the functions $B(x)=(2x-1)^2e^{4x}$, $A(x)=ce^{-Ax}-e^{-cAx}$, and $C(x)=B(x)A(x)$. We have:
\[
B(0)=1,\ B\left(\frac{1}{2} \right )=0\ \nor{and}\ B'(x)= 8x(2x-1)e^{4x}.
\]
Thus, $B'(x)\leq 0$ in $\left[0, \frac{1}{2} \right]$, therefore $B(x)$ is a decreasing and positive function in $\left[0, \frac{1}{2} \right]$.

For  $A(x)$, we have:
\[
A(0)=c-1,\quad A\left(\frac{1}{2}\right) = e^{-\frac{A}{2}}\left( c - e^{-(c-1)\frac{A}{2}} \right) > 0,\quad \nor{and}\quad A'(x)=cA(-e^{-Ax}+e^{-cAx}).
\]
Thus, $A'(x)\leq 0$ in $\left[0, \frac{1}{2} \right]$ (since $A>1$), so $A(x)$ is a decreasing and positive function in $\left[0, \frac{1}{2} \right]$ too.

% mimmo \scalebox{1.2}{$(\tfrac{1}{2})$}
Let us consider $C(x)=B(x)A(x)$. We have:
\[
C(0)=c-1, \quad  C\left(\frac{1}{2}\right) =0, \quad \nor{and} \quad C'(x)=B'(x)A(x)+A'(x)B(x).
\]
Therefore, thanks to the properties of $A(x),B(x)$ and of their derivatives, also $C(x)$ is a decreasing and positive function in $\left[0, \frac{1}{2} \right]$ and in particular $C(0)=c-1$. Hence:
\[
c-1\ \geq (2x-1)^2e^{4x}[ce^{-Ax}-e^{-cAx}]\ \nor{in}\ \left[ 0,\textstyle{\frac{1}{2}} \right].
\]
For the second interval, $\left[\frac{1}{2}, 1 \right]$, the proof is similar.

The proof for the case $\al < \be < 0$ proceeds likewise. \qed 

This result can be extended to two $[\al, {\theta}_1, {\theta}_2]$-defined functions.

\begin{lemma} Let $f$ be an $[\al, {\theta}_1, {\theta}_2]$-defined function and $g$ a $[\be, {\theta}_1, {\theta}_2]$-defined function of the same type (both single-, double- or special-defined), with $| \al | > |\be |$; then $ |f|\geq |g|$ in $[0,1]$.
\end{lemma}
\dimostraz The single-single case is \Lem{lem:1.9}. Let us consider the double-double case. By \Def{def:1.4}, both $f$ and $g$ are built up from two single-defined functions rescaled in the interval $[0, \frac{1}{2}]$ and $[\frac{1}{2}, 1]$. The claim easily follows by applying the previous lemma to these single-defined functions. 

The special-special case is similar, with the interval $[0,1]$ split into three parts, instead of two.  \qed 

In a specific step of the algorithm-correctness proof, we will need the following lemma, together with its subsequent generalization.

\begin{lemma}\label{lem:opens} Let $\sI=\{I_k \, | \, k \! \in  \sK \}$ be a finite set of open, bounded non-empty real intervals indexed by a finite set $\sK$, with $I_k={]\al_k, \be_k[}$, equipped with a partial order $\leq$. If the condition
\[
\forall i,j \in \sK \ \big( I_j \leq I_i \Rightarrow \al_j < \be_i \big)
\]
holds, then there exists a collection  $\{ \phi_k \, | \, k \! \in \! \sK \}$ of elements such that $\phi_k \! \in \! I_k$ and if $I_j \leq I_i$, then $\phi_j \leq \phi_i$.     
\end{lemma}

\dimostraz Given $I_k \in \sI$, let us define:
\[
\bar{\be}_k \putAs \min \{ \be_j \, | \, I_j > I_k \} \ \ \mbox{and} \ \ \bar{\phi}_k \putAs \max \{ \phi_j \, | \, I_k > I_j \}.
\]
$\phi_k$ is defined by induction over $\leq$ as follows:
\begin{itemize}

    \item if $I_k$ is a minimal element with respect to $\leq$, we set:
    \[
       \phi_k \putAs \frac{\al_k + \min\{\be_k, \bar{\be}_k\}}{2};
    \]
    \item assume that, for all $I_j \leq I_k$, $\phi_j$ is defined, then we set:
    \[
       \phi_k \putAs \frac{\max\{\al_k,\bar{\phi}_k\} + \min\{\be_k, \bar{\be}_k\}}{2}.
    \]
\end{itemize}
The following two properties are now proved by induction on $\leq$:
\begin{itemize} 

    \item $\phi_k \! \in \! I_k$, i.e., $\al_k < \phi_k < \be_k$;

    \item if $I_j \leq I_k$, then $\phi_j \leq \phi_k$.

\end{itemize}

\noindent \ita{Base case:} If $I_k$ is minimal with respect to $\leq$, then $\al_k < \phi_k = \frac{\al_k + \min\{\be_k, \bar{\be}_k\}}{2} < \be_k$ and the second property is vacuously true.

\noindent \ita{Inductive step:} In this case $\phi_k = \frac{\max\{\al_k,\bar{\phi}_k\} + \min\{\be_k, \bar{\be}_k\}}{2}$. Assuming that $\bar{\phi}_k = \phi_h$ , with $I_h < I_k$, and that the two properties are valid for all $I_j < I_k$, we prove that they also apply to $I_k$. The following properties hold:
\[
\begin{array}{rl} \vspace{0.1 cm}
{\al}_k \! < \! {\be}_k : & \mbox{by construction}, \\ \vspace{0.1 cm}
{\al}_k \! < \! {\bar{\be}}_k: & \mbox{because if}\  I_g \! \geq \! I_k \ \mbox{then}\ {\be}_g \! > {\al}_k , \\ \vspace{0.1 cm}
{\phi}_h \! < \! {\be}_k: & \mbox{since}\ {\phi}_h=\frac{\max \{ {\al}_h , {\bar{\phi}}_h \} + \min \{ {\be}_h , {\bar{\be}}_h \} }{2}\ \mbox{and thus}\ {\phi}_h \! < \! {\bar{\be}}_h \! \leq \! {\be}_k ,\\ \vspace{0.1 cm}
{\phi}_h \! < \! {\bar{\be}}_k : & \mbox{because}\ I_k \! \geq \! I_h \ \mbox{and thus}\ {\phi}_h \! < \! {\bar{\be}}_h \! \leq \! {\bar{\be}}_k ,\\
\max \{ {\al}_k, {\bar{\phi}}_k \}\! < \! \min \{ {\be}_k , {\bar{\be}}_k \} : & \mbox{by the previous properties}.
\end{array}
\]
From the last point we obtain that:
\[
\al_k \leq \max \{ {\al}_k, {\bar{\phi}}_k \} <  \phi_k  <  \min \{ {\be}_k , {\bar{\be}}_k \}  \leq \be_k,
\]
concluding the inductive step. \eod

The previous lemma can be generalized as follows.

\begin{lemma}\label{lem:intervals} Let $\sI=\{I_k \, | \, k \! \in \! \sK \}$ be a finite set of bounded non-empty real intervals indexed by $\sK$, with $\al_k \putAs \inf I_k$ and $ \be_k \putAs \sup I_k$, furnished with a partial order $\leq$. If the condition
\[
\forall i,j \in \sK \ \big( I_j \leq I_i \, \Rightarrow \, \exists x,y \,( x \! \in \! I_j \et y \! \in \! I_i \et x \leq y ) \big)
\]
holds, then there exists a collection of elements $\{ \phi_k \, | \, k \! \in \! \sK \}$, with $\phi_k \! \in \! I_k$, such that if $I_j \leq I_i$, then $\phi_j \leq \phi_i$. 

\end{lemma}
\dimostraz The proof of \Lem{lem:opens} can be easily extended to the general case. \eod



At the end of this part, we recall some useful properties about continuous and differentiable real functions and their derivatives.
\begin{lemma}\label{lem:1.11} Let $f \colon[a,b]\frec \mR$ be a continuous and differentiable function defined in $[a,b]$. Let $k\in \mR$ and suppose $f'(x)\geq k$ (resp. $\leq $) for all $x\in [a,b]$. If $\frac{f(b)-f(a)}{b-a}=k$ then $f$ is linear in $[a,b]$, and $f'(x)=k$ holds for all $x\in [a,b]$.
\end{lemma}
\dimostraz The proof is a straightforward application of the mean value theorem and is omitted here. \qed 

\begin{lemma}\label{lem:1.12}
Let $f \colon[a,b]\frec \mR$ be a continuous and differentiable function defined in $[a,b]$. Suppose $f$ be convex (resp. concave) in $[a,b]$. If $\frac{f(b)-f(a)}{b-a}$ is equal to $f'(a)$ or $f'(b)$, then $f$ is linear in $[a,b]$, and $f'(x)=f'(a)$ holds for all $x\in [a,b]$.
\end{lemma}
\dimostraz We omit the proof, which is again a straightforward application of the mean value theorem. \qed 

\begin{lemma}\label{lem:1.13}
Let $f,\ g$ be real functions defined and differentiable in the closed and bounded interval $[ a ,b ]$, endowed with the second derivative in $a$. If $f(a) \! = \! g(a)$, $f'(a)=g'(a)$ and $f''(a) > g''(a)$, then there exists $c \! \in ]a , b[$ such that $f(x) \! > \! g(x)$ for all $x \! \in ]a, c[$.
\end{lemma}
\dimostraz We have:
\[
f''(a) > g ''(a) ~~\Longleftrightarrow~~ f''(a) - g''(a) >0 ~~\Longleftrightarrow~~ (f'-g')'(a) >0.
\]
Therefore, $(f'-g')'$ is an increasing function in $a$, then there exists $c \! \in ]a , b[$ such that:
\[
f'(x)-g'(x) > f'(a)-g'(a) = 0,
\]
for all $x \! \in ]a , c[$. Let $\bar{x} \! \in ]a ,c]$. Because of the Mean Value theorem there exists $ \ep \! \in ]a, \bar{x} [$:
\[
(f(\bar{x})-g(\bar{x}))-(f(a)-g(a)) = (f'(\ep) - g'(\ep )) \x (\bar{x} - a).
\]
We have $f'(\ep ) - g'( \ep ) > 0$ and $f(a) \! = \! g(a)$. Then $f(\bar{x}) - g(\bar{x}) \! > \! 0$, thus $ f(\bar{x}) \! > \! g(\bar{x})$. \qed 

\begin{lemma}\label{lem:1.14} Let $f,\ g$ be two real functions defined and derivable in the closed and bounded interval $[a , b]$, with $f(a) \! = \! g(a)$ (resp. $f(b) \! = \! g(b)$). If $f(x) \! > \! g(x)$ for all $x \! \in ]a , b[$, then $f'(a) \! \geq \! g'(a)$ (resp. $f'(b) \! \leq \! g'(b)$).
\end{lemma} 

\dimostraz We consider the case $f(a) \! = \! g(a)$; the case $f(b) \! = \! g(b)$ can be treated likewise.\\
From the hypotheses we get:
\[
\scalebox{1.2}{$\frac{ (g(x)-f(x))-(g(a)-f(a))}{x-a}$} <0
\]
for every $x \in {]a ,b[}$; then
\[
\textstyle g'(a)-f'(a)=(g-f)'(a) = \lim_{x\frec a^+} \scalebox{1.2}{$\frac{(g(x)-f(x))-(g(a)-f(a))}{x-a}$}  = \lim_{x\frec a^+} \scalebox{1.2}{$\frac{(g(x)-f(x))-(g(a)-f(a))}{x-a}$} \leq 0.
\]

Thus, $f'(a) \! \geq \! g'(a)$. \qed 









\subsection{Correctness}\label{subsec:correctness}

In this section, we prove the correctness of the decision procedure previously described.

\begin{theorem} The two last formulas ${\fhi}_3$ and ${\fhi}_4$ of the decision algorithm for \RDFp  theory are equisatisfiable.
\end{theorem}
\dimostraz The idea behind the proof is that if a model, however complex, for ${\fhi}_3$ exists, then it is possible to build a simplified model that involves only functions defined as piecewise exponential functions. 

Let $F$ and $V \! =\! \{v_1, v_2, \dots , v_r\} $ be, respectively, the set of the function variables and the set of the ordered domain variables of ${\fhi}_3$.

Given an arbitrary model $M$, let $MV = \{{\eta}_i \in \mR \, |\,  {\eta}_i = Mv_i,\ \mbox{with}\ v_i \in V \}$ be the set of all real values associated with the domain variables in $V$ by $M$.
Moreover, let $\bar{v}$ denote the interpretation $Mv$ of the numerical variable $v$ under the model $M$; this notation also holds for numeric variables that are not domain variables.

The proof consists of two parts.

\noindent {\boldmath\large${\fhi}_4 \imp {\fhi}_3 )$} Let $M$ be a model for $\fhi_4$; our goal is to construct a model that satisfies $\fhi_3$. Specifically, we aim at extending $M$ to include the function variables appearing in $\fhi_3$ in a way ensuring that all clauses in ${\fhi}_3$ are satisfied.

The approach involves considering, for each function variable $f$, an appropriate perturbation of the piecewise function that passes through all points $(\bar{v}_i,\bar{y}_i^f)$ where $v_i \! \in \! V$. The perturbation we apply will take the form of an exponential adjustment built up using $[\al ,{\theta}_1, {\theta}_2]$-defined functions; the proof will amount to showing that for $\al \! >\! 0$  small enough all clauses in ${\fhi}_3$ will be satisfied.

For simplicity, we define the real value
\[
{\theta}_i^f (u) \putAs ({\eta}_{i+1}-{\eta}_i )\x u -({\bar{y}}_{i+1}^f -{\bar{y}}_i^f ),
\] 
for each function variable $f \! \in \! F$ and for each $i \! \in \! \{ 1,2,\dots , r-1\}$, where $u\in \mR $ is a suitable parameter.

Consider the following sets:
\begin{align*}
A_1 & \putAs    \left\{{\theta}_j^f (u)\! \in \! \mR |\, j \! \in \! \{ 1,2,\dots ,r-1 \} \ \mbox{and} \ u \! \in \! \{ {\bar{t}}_j^f ,{\bar{t}}_{j+1}^f \} \right\} ,\\
A_2 & \putAs    \left\{ \textstyle{\frac{1}{2}}({\bar{y}}_j^f -{\bar{y}}_j^g ) \! \in \! \mR |\, (f>g)_{[w_1, w_2 ]}\ \mbox{occurs in}\ {\fhi}_3 \ \mbox{and} \ j \! \in \! \{ \ind(w_1), \dots , \ind(w_2) \}   \right\}, \\
A_3 & \putAs    \left\{ {\theta}_j^f (\bar{y}) \! \in \! \mR |\, (D[f]\bowtie y)_{[z_1 ,z_2]}\ \mbox{occurs in} \ {\fhi}_3 \ \mbox{and} \ j\! \in \! \{ \ind(z_1), \dots, \ind(z_2)-1 \}    \right\}, \\
A_4 & \putAs   \left\{ {\theta}_j^f (0) \! \in \! \mR |\, \mbox{Strict}\_ \mbox{Up} (f)_{[z_1, z_2]}\ \mbox{or}\ \mbox{Strict}\_ \mbox{Down}(f)_{[z_1 z_2]}\ \mbox{occur in}\ {\fhi}_3    \mbox{ and }  j \! \in \! \{ \ind(z_1), \dots , \ind(z_2)-1 \}   \right\},
\end{align*}
and, let
\[
A \putAs \left\{ |x| \in {\mR}^+  \Bigg|  \ x\in \bigcup_{i=1}^4 A_i,\, x\not= 0 \right\} .
\]

In the trivial case $A  =  \emptyset $, put $m  =  0$ and $\I =\{ 0\}$, the following proof is then straightforward; otherwise, pick $m \! \in \! {\mR}^+$ so that it satisfies $0<m<\mbox{min}(A)$ and let $\I$ be the set $]0, \frac{1}{8}m[$.

For each function variable $f \in  F$, we introduce the following function family $\{ (Mf)_{\al}{\}}_{\al \in \I }$, with $(Mf)_{\al} \colon \mR \frec \mR $ defined as:\footnote{To properly treat literals of the form $(f>g)_A$ over unbounded intervals, a refinement of this definition is needed; to avoid cluttering, this further enrichment is presented only in the part of the proof where it is required.}
\begin{align*}
(Mf)_{\al}(\eta ) &\putAs 
\begin{cases}
{\bar{y}}_1^f +({\bar{\ga}}_0^f -{\bar{t}}_1^f )(1-e^{\eta -{\eta}_1})+{\bar{\ga}}_0^f ({\eta}_1 -\eta ) & \text{if }\ \eta \! \in ]-\infty , {\eta}_1[,\\[.1cm]
s_i^f (p_i (\eta ))+ c_i^f (p_i (\eta )) & \text{if }\ \eta \! \in \! [{\eta}_i, {\eta}_{i+1} [,\\[.1cm]
{\bar{y}}_r^f +( {\bar{t}}_r^f - {\bar{\ga}}_r^f)(1-e^{{\eta}_r -\eta})+{\bar{\ga}}_r^f (\eta -{\eta}_r ) & \text{if }\ \eta \! \in \! [ {\eta}_r, +\infty[,
\end{cases}
\intertext{with:}
s_i^f (x) &\putAs \bar{y}_i^f +(\bar{y}_{i+1}^f -\bar{y}_i^f)\x x, & \forall x \! \in \! [0,1] \\
p_i (\eta ) &\putAs \frac{\eta -{\eta}_i}{{\eta}_{i+1} -{\eta}_i}, & \forall \eta \! \in \! [{\eta}_i ,{\eta}_{i+1}]
\end{align*}
and $c_i^f  \colon  [0,1]\frec \mR$ is the $[\al ,{\theta}_i^f (\bar{t}_i^f ), {\theta}_i^f (\bar{t}_{i+1}^f )]$-defined function.

Here, $p_i$ denotes the projection from $[{\eta}_i ,{\eta}_{i+1}]$ to $[0,1]$; thus, $s_i^f (p_i (\eta ))$ is simply the linear interpolant between $({\eta}_i ,\bar{y}_i^f )$ and $({\eta}_{i+1}, \bar{y}_{i+1}^f )$, whereas $c_i^f (p_i (\eta ))$ is the exponential perturbation that adjust the function to satisfy the conditions on the derivative.

The following result is the basis of our theorem:
\begin{lemma}\label{lem:2.2} Let $f\! \in \! F$ be a function variable occurring in ${\fhi}_3$ and let $\al \! \in \! \I$. Then $(Mf)_{\al}$ is a continuous and differentiable function defined on $\mR $, with a continuous derivative,  and we have, for each $i\! \in \! \{ 1, 2, \dots ,r\}$:
\[
(Mf)({\eta}_i)=\bar{y}_i^f ,\ \ and\ \ (Mf)'({\eta}_i)=\bar{t}_i^f\,.
\]
\end{lemma}
\dimostraz Let $\al \! \in \! \I$. Initially we have to verify that the function $(Mf)_{\al}(\eta)$ is well-defined for each $\eta \! \in \! \mR$. For each $i \! \in \! \{ 1, 2, \dots , r-1 \}$, we have ${\theta}_i^f ({\bar{t}}_i^f )= {\theta}_i^f ({\bar{t}}_{i+1}^f)=0$ or
\[
0<|4\al |<m<\mbox{min}\{ |x| \in T|\ x\not= 0\},\ \mbox{where}\ T=\{ {\theta}_i^f ({\bar{t}}_i^f),  {\theta}_i^f ({\bar{t}}_{i+1}^f) \},
\]
because of the minimality of $m$ with respect to $A$; the existence of the $[\al , {\theta}_i^f ({\bar{t}}_i^f), {\theta}_i^f ({\bar{t}}_{i+1}^f)]$-defined functions $c_i^f$ is then given by \Lem{lem:1.8}.\\
We have $(Mf)({\eta}_r)={\bar{y}}_r^f$, and for each $i \! \in \! \{ 1, 2, \dots , r-1 \}$ it holds that $ (Mf)({\eta}_i)=s_i^f (p_i ({\eta}_i)) + c_i^f (p_i ({\eta}_i )) ={\bar{y}}_i^f $ because $c_i^f (0)=0$.\\
The function is continuous and differentiable, with a continuous derivative, in each interval $]-\infty , {\eta}_1 [,\ ]{\eta}_i , {\eta}_{i+1}[$ with $i \! \in \! \{1, 2, \dots , r-1 \}$, $]{\eta}_r, +\infty [$. Furthermore, for each $j \! \in \! \{ 1, 2, \dots , r\}$:
\[
\lim_{\eta \, \frec {\eta}_j^{-}} (Mf)_{\al}(\eta) = (Mf)_{\al}({\eta}_j )= \lim_{\eta \, \frec {\eta}_j^{+}} (Mf)_{\al}(\eta ),
\] 
thus, the function is continuous in $\mR$.

About differentiability, we have for each $j\in \{ 1, 2, \dots , r-1 \}$:
\begin{align*}
\lim_{\eta \frec {\eta}_j^{+}} (Mf)_{\al}'(\eta ) & = \lim_{\eta \frec {\eta}_j^{+}} \left[ (s_j^f (p_j))'(\eta ) + (c_j^f(p_j))'(\eta) \right] \\
 & = \lim_{\eta \frec {\eta}_j^{+} }   p_j'(\eta) \x { \left[ (s_j^f)'(x) + \x (c_j^f)'(x)\right] }_{ x=p_j (\eta) } \\
 & = \lim_{x \frec 0^{+}}   p_j'({\eta}_j ) \x \left[ (s_j^f)'(x) + (c_j^f)'(x) \right] \\
&  = \left[ ({\bar{y}}_{j+1}^f - {\bar{y}}_j^f )+ {\theta}_j^f ({\bar{t}}_j^f )\right] \x \frac{1}{{\eta}_{j+1}- {\eta}_j} \\
& = {\bar{t}}_j^f =\lim_{\eta \frec {\eta}_j^{-}} (Mf)_{\al}'(\eta ),
\end{align*}
because $(c_j^f)'(0)= {\theta}_j^f ({\bar{t}}_j^f)$.

Moreover, the following holds:
\[
\lim_{\eta \, \frec {\eta}_1^-}(Mf)_{\al}'(\eta) = \lim_{\eta \, \frec {\eta}_1^-} \left[ {\bar{\ga}}_0^f + ({\bar{t}}_1^f - {\bar{\ga}}_0^f )e^{\eta - {\eta}_1 } \right] = {\bar{t}}_1^f = \lim_{\eta \, \frec {\eta}_1^+}(Mf)_{\al}'(\eta );
\]
and the point ${\eta}_r$ can be treated in the same way.

Thus, $(Mf)_{\al}$ is differentiable with a continuous derivative on $\mR$, and we have $(Mf)_{\al}'({\eta}_j )= {\bar{t}}_j^f$ for each $j \in \{ 1, 2, \dots ,r \}$. \qed 

The remaining nontrivial task is to demonstrate that, for a sufficiently small $\al$ (since $\al$ is the only free parameter in the definition of $(Mf)_{\al}$), $(Mf)_{\al}$ satisfies all clauses of $\fhi_3$, such as $(f>g)_{[w_1 ,w_2 ]}$ or $(f \not= g)_{[z_1 ,z_2 ]}$. To establish this, we examine each type of clause and prove that, for some appropriate $\al>0$, these clauses hold true in our extended real model $M$. Given that there are a finite number of clause types and intervals, this suffices to prove the claim.
In the discussion that follows, we generally omit the subscript $\al$ for simplicity.

\paragraph{Case \boldmath($f$):}
Let $x\! =\! f(v_j)$ be a literal occurring in ${\fhi}_3$ for some $j\! \in \! \{ 1, 2, \dots ,r\}$.

 We have:
\[
M(f(v_j))=(Mf)(Mv_j)=(Mf)({\eta}_j)=\bar{y}_j^f =My_j^f =Mx
\]
where the last equality is true because the literal $x=y_j^f$, introduced in step \ref{itemAlgoThree}), occurs in ${\fhi}_4$.

\paragraph{Case \boldmath($D$):}
Let $x\! = \! D[f](v_j)$ be a literal occurring in ${\fhi}_3$ for some $j\! \in \! \{ 1, 2, \dots ,r\}$. Analogously to the previous case, in step \ref{itemAlgoThree}) the literal $x\! =\! t_j^f$ was added, and we have:
\[
M(D[f](v_j))=(Mf)'(Mv_j)=(Mf)'({\eta}_j)=\bar{t}_j^f =Mt_j^f =Mx.
\] 


\paragraph{Case \boldmath$(f\mathord{=})$:}
Let $(f=g)_{[z_1 z_2]}$ be a literal occurring in ${\fhi}_3$ and let $Mz_1 \! \leq \! Mz_2$, otherwise the literal is vacuously true. We have to verify that for each $\eta \! \in \! [Mz_1, Mz_2]\subset \mR$ the following holds:
\[
(Mf)(\eta )=(Mg)(\eta ).
\]
Such equality holds for each ${\eta}_i \! \in \! MV$ with $i\! \in \! \{ \ind(z_1), \dots ,\ind(z_2)\}$ since, from clauses in step \ref{itemAlgoFour}.\ref{alg4:actA}), we have:
\[
(Mf)({\eta}_i )=\bar{y}_i^f =\bar{y}_i^g =(Mg)({\eta}_i ).
\] 
The equality also holds for each $\eta \! \in  ]{\eta}_j, {\eta}_{j+1}[$ with $j\! \in \! \{ \ind(z_1) ,\dots , \ind(z_2)-1 \}$:
\[
\begin{array}{lll} \vspace{0.05 cm}
(Mf)(\eta ) & = & s_j^f (p_j (\eta )) +c_j^f (p_j (\eta ))= \\
            & = & s_j^g (p_j (\eta )) + c_j^g (p_j (\eta ))=(Mg)(\eta ),
\end{array}            
\]
where $c_j^f (p_j (\eta ))\! =\! c_j^g ( p_j (\eta ))$ for each $\eta \! \in \! [{\eta}_j ,{\eta}_{j+1}]$ derives from \Cor{cor:1.3} and the conditions ${\theta}_j^f (\bar{t}_j^f )\! =\! {\theta}_j^g (\bar{t}_j^g )$ and ${\theta}_j^f (\bar{t}_{j+1}^f ) \! =\! {\theta}_j^f (\bar{t}_{j+1}^f )$, which hold because of the literals $t^f_i=t^g_i$ introduced in step \ref{itemAlgoFour}.\ref{alg4:actA}).

The proof for the extremal intervals, $]\! -\! \infty , {\eta}_1 ]$ and $[{\eta}_r, +\infty [ $, derives directly from the definition of $(Mf)$ in them, since ${\bar{\ga}}_0^f = {\bar{\ga}}_0^g$ and  ${\bar{\ga}}_r^f = {\bar{\ga}}_r^g$, again because of the literals added in step \ref{itemAlgoFour}.\ref{alg4:actA}).


\paragraph{Case \boldmath $(f\mathord{>})$:} Since the treatment of atoms of the form $(f>g)_A$ required different cases and sub-cases, we start with a presentation of the general structure of the completeness proof for this type of literals. 

\emph{First, we consider three subcases: bounded and closed intervals; bounded and open or semi-open intervals; unbounded and closed intervals. Moreover, the treatment for open or semi-open intervals requires itself some case distinctions depending on the type of the interpolating functions involved, i.e. single-, double- or special-defined.}

\paragraph{Subcase \boldmath $(f\mathord{>})$, bounded and closed intervals:}

We start analyzing this case by treating bounded and closed intervals.

Let $(f>g)_{[w_1, w_2]}$ be a literal occurring in ${\fhi}_3$ and let $Mw_1 \leq Mw_2 $, otherwise the literal is vacuously true. We have to verify that for each $\eta \in [Mw_1 ,Mw_2 ] \subset \mR$ the following holds:
\[
(Mf)(\eta) > (Mg)(\eta) .
\] 
This is true for each ${\eta}_i \! \in  \! MV$ with $i \! \in \! \{ \ind(w_1), \dots, \ind(w_2) \}$, since $(Mf)({\eta}_i) = {\bar{y}}_i^f > {\bar{y}}_i^g = (Mg)({\eta}_i)$ from clauses introduced in step \ref{alg4:actionB:case1}.

Moreover, the above inequality also holds for each $\eta \! \in \! [{\eta}_j , {\eta}_{j+1} ]$ with $j\in \{ \ind(w_1), \dots, \ind(w_2)-1 \}$. In fact, consider the points $\left( 0, \frac{1}{2} ({\bar{y}}_j^f +{\bar{y}}_j^g) \right)$ and $\left( 1, \frac{1}{2} ({\bar{y}}_{j+1}^f +{\bar{y}}_{j+1}^g) \right)$ in ${\mR}^2 $, and let $r_j(x)$ be the straight line interpolating such points:
\[
r_j(x)= \frac{1}{2} \left({\bar{y}}_{j+1}^f +{\bar{y}}_{j+1}^g - {\bar{y}}_j^f -{\bar{y}}_j^g \right)\x x + \frac{1}{2}\left({\bar{y}}_j^f + {\bar{y}}_j^g\right),\ \ \forall x\in [0,1].
\]
The sought inequality $(Mf)(\eta) > (Mg)(\eta)$ follows from the fact that, for $\al$ sufficiently small, the functions $(Mf)(\eta)$ and $(Mg)(\eta)$ lie, respectively, above and below the straight line $r_j (p_j (\eta))$ when $\eta$ ranges over the interval $[{\eta}_j ,{\eta}_{j+1}]$. In particular, let
\[
l \putAs \mbox{max}\left\{ \frac{1}{2} ({\bar{y}}_j^g - {\bar{y}}_j^f), \frac{1}{2} ({\bar{y}}_{j+1}^g - {\bar{y}}_{j+1}^f) \right\};
\]
we have:
\[
l=\underset{x\in [0,1]}{\mbox{max}} [r_j (x) - s_j^f (x) ]\geq r_j(x) - s_j^f (x),\ \ \forall x\in [0,1]. 
\]
By the minimality of $\al$ with respect to $A$,  $0<\! \al \! <\! \frac{1}{2} ({\bar{y}}_j^f - {\bar{y}}_j^g )$ and $0<\! \al \! <\!  \frac{1}{2}({\bar{y}}_{j+1}^f - {\bar{y}}_{j+1}^g)$ hold, and by \Lem{lem:1.7}, we have $| c_j^f(x)| \leq \al$ for each $x\in [0,1]$; hence, we conclude:
\[
c_j^f(x) \geq -\al > l\geq r_j(x)-s_j^f(x),\ \ \forall x\in [0,1].
\]
Analogously, we have $c_j^f (x) < r_j(x) - s_j^g(x)$ for each $x\in [0,1]$.

Thus, for each $\eta \in  [{\eta}_j, {\eta}_{j+1}]$:
\[
(Mf)(\eta)= { \left[ s_j^f(x) + c_j^f(x) \right] }_{x=p_j (\eta)} > {[ r_j (x)]}_{x=p_j (\eta)} > (Mg)(\eta) .
\]
Now we consider the case of open or semi-open bounded intervals that is the most involved one.

\smallskip

\paragraph{Subcase \boldmath $(f\mathord{>})$, bounded and open or semi-open intervals:}

Let $(f>g)_{]w_1, w_2[}$ be a literal that occurs in ${\fhi}_3$ and $w_1 = v_k , v_{k+1} , \dots , v_{k+n} = w_2 $ the $n+1$ domain variables inside $[w_1, w_2]$; because of step \ref{alg1:action2:case3} of the algorithm, $n\! \geq \! 2$, i.e., there is at least one domain variable $v$ such that $w_1 \! \! < \!  \! v \! < w_2$. These variables divide $[w_1 , w_2]$ into $n$ intervals $ [v_k , v_{k+1}],\ [v_{k+1}, v_{k+2}],$ $ \dots , [v_{k+n-1} , v_{k+n}]$. Let us first consider the $n-2$ intervals $[v_{k+1} ,v_{k+2}], \dots , [v_{k+n-2} , v_{k+n-1}]$ (if $n=2$ there are no such intervals). Since these intervals are closed and bounded, we can apply the same strategy used before. It remains to be proved that $f$ exceeds $g$ in the two extremal intervals $] v_k , v_{k+1}] = ]w_1 , v_{k+1}]$ and $[v_{k+n-1} , v_{k+n}[ = [v_{k+n-1}, w_2 [$.

Our treatment is limited to the interval $]v_k, v_{k+1}]= ]w_1 , v_{k+1}]$, the other case being closely analogous. We want to prove that, when $\al \! \in \! I$ is sufficiently small, $(Mf)_{\al} (\eta) \! > \! (Mg)_{\al} (\eta)$ holds for all $ \eta \in ]{\eta}_k , {\eta}_{k+1}]$; in the following, it will be necessary to make the value $\al$ explicit. We begin by proving the following two propositions.

\begin{proposition}\label{prop:2.3} Given a model $M$ as before,  for every $\bar{\eta} \!  \in  ]{\eta}_k ,{\eta}_{k+1}]$ there exists an $\bar{\al} \! \in \! \I$ such that for every $\eta \! \in ]{\bar{\eta}} , {\eta}_{k+1}]$ we have $(Mf)_{\bar{\al}}(\eta) \! > \! (Mg)_{\bar{\al}}(\eta)$. Moreover, this holds for every $\al \!  \in \! \I$ such that $\al < \bar{\al}$.
\end{proposition}

\dimostraz Because of the steps \ref{itemAlgoOne}.\ref{alg1:actionOne}) and \ref{itemAlgoFour}) of the algorithm, we have ${\bar{y}}_k^f = {\bar{y}}_k^g$. Therefore, for every $\eta \in ]{\eta}_k , {\eta}_{k+1}]$ and for every $\al \in \I$, we have:
\[
\begin{aligned}
&(Mf)_{\al} (\eta) > (Mg)_{\al} (\eta)\\
&\qquad \qquad \Longleftrightarrow~~ (Mf)_{\al} (\eta) - (Mg)_{\al} (\eta) >0 \\
&\qquad \qquad \Longleftrightarrow~~ s_k^f (p_k (\eta)) + c_k^f (p_k (\eta)) -s_k^g (p_k (\eta)) -c_k^g (p_k (\eta)) >0 \\
&\textstyle \qquad \qquad \Longleftrightarrow~~ {\bar{y}}_k^f + ({\bar{y}}_{k+1}^f - {\bar{y}}_k^f) \x \frac{\eta - {\eta}_k }{{\eta}_{k+1} - {\eta}_k} + c_k^f (p_k (\eta )) - {\bar{y}}_k^g - ( {\bar{y}}_{k+1}^g - {\bar{y}}_k^g ) \x \frac{\eta - {\eta}_k}{{\eta}_{k+1} - {\eta}_k} - c_k^g (p_k (\eta ))>0 \\
&\textstyle \qquad \qquad \Longleftrightarrow~~\ \ -c_k^f (p_k (\eta )) + c_k^g (p_k (\eta )) < \left( \frac{{\bar{y}}_{k+1}^f - {\bar{y}}_{k+1}^g}{{\eta}_{k+1} - {\eta}_k} \right) \x ( \eta - {\eta}_k )~~~~~~~~~~(\mbox{remembering that}\ {\bar{y}}_k^f = {\bar{y}}_k^g ).
\end{aligned}
\]
Because of step \ref{itemAlgoFour}.\ref{alg4:actC}) and \Lem{lem:1.7} we have ${\bar{y}}_{k+1}^f - {\bar{y}}_{k+1}^g >0$ and also:
\[
-c_k^f (p_k (\eta )) + c_k^g (p_k (\eta )) \leq | -c_k^f (p_k (\eta )) + c_k^g (p_k (\eta ))| \leq | c_k^f (p_k (\eta )) | + | c_k^g (p_k (\eta )) | \leq 2\al .
\]
It is sufficient to take $\al < \left( \frac{{\bar{y}}_{k+1}^f - {\bar{y}}_{k+1}^g}{{\eta}_{k+1} - {\eta}_k} \right) \x \frac {( \bar{\eta} - {\eta}_k )}{2}$. \qed 

\begin{proposition}\label{prop:2.4} Given a model $M$ as before, for every $\al \! \in \! \I$ sufficiently small, there exists an $\bar{\eta} \! \in ] {\eta}_k , {\eta}_{k+1}]$ such that $(Mf)_{\al} (\eta) > (Mg)_{\al}(\eta )$ for all $\eta \in ]{\eta}_k , \bar{\eta}]$.
\end{proposition}

\dimostraz Because of step \ref{itemAlgoFour}.\ref{alg4:actC}) of the algorithm, we have ${\bar{t}}_k^f \geq {\bar{t}}_k^g$, from this (by \Lem{lem:2.2}) it follows that for every $\al \! \in \! \I$ we have $(Mf)_{\al}'({\eta}_k) \geq (Mg)_{\al}'({\eta})$. We now separately consider the two cases ${\bar{t}}_k^f > {\bar{t}}_k^g$ and ${\bar{t}}_k^f = {\bar{t}}_k^g$.



If ${\bar{t}}_k^f > {\bar{t}}_k^g$, for every $\al \in \I$ we have:
\[
\begin{aligned}
(Mf)_{\al}'({\eta}_k) > (Mg)_{\al}'({\eta}_k) &~~\Longleftrightarrow~~   (Mf)_{\al}'({\eta}_k) - (Mg)_{\al}'({\eta}_k) > 0\\
&~~\Longleftrightarrow~~ ((Mf)_{\al}-(Mg)_{\al})'({\eta}_k)>0.
\end{aligned}
\]
Thus, $(Mf)_{\al} - (Mg)_{\al}$ is an increasing function in ${\eta}_k$. Moreover, since ${\bar{y}}_k^f = {\bar{y}}_k^g$ we have:
\[
(Mf)_{\al}({\eta}_k) = (Mg)_{\al}({\eta}_k),
\]
and therefore 
\[
(Mf)_{\al}({\eta}_k) - (Mg)_{\al}({\eta}_k)=0
\]
and there exists an $\bar{\eta}$ such that
\[
(Mf)_{\al}({\eta}) - (Mg)_{\al}({\eta})>0\ \ \ \forall \eta \in ]{\eta}_k ,\bar{\eta}],
\]
and hence
\[
(Mf)_{\al}({\eta}) > (Mg)_{\al}({\eta}) \ \ \ \forall \eta \in ]{\eta}_k , \bar{\eta} ].
\]

If ${\bar{t}}_k^f = {\bar{t}}_k^g $, the following equivalences hold:
\[
\begin{aligned}
{\bar{t}}_k^f = {\bar{t}}_k^g &~\Longleftrightarrow~ (Mf)_{\al}'({\eta}_k) = (Mg)_{\al}'({\eta}_k) \\
&~\Longleftrightarrow~  (s_k^f (p_k))'({\eta}_k) + (c_k^f (p_k))'({\eta}_k) = (s_k^g (p_k))'({\eta}_k) + (c_k^g (p_k))'({\eta}_k) ~  (\mbox{\small opening the two derivatives})~\\
&~\Longleftrightarrow~
\textstyle \frac{{\bar{y}}_{k+1}^f-{\bar{y}}_k^f}{{\eta}_{k+1} - {\eta}_k} + (c_k^f (p_k))'({\eta}_k) = \frac{{\bar{y}}_{k+1}^g - {\bar{y}}_k^g}{{\eta}_{k+1} - {\eta}_k} + (c_k^g (p_k))'({\eta}_k).
\end{aligned}
\]
We observe that
\[
\textstyle (c_k^f (p_k))'({\eta}_k) = {\theta}_k^f ({\bar{t}}_k^f) \x \frac{1}{{\eta}_{k+1} - {\eta}_k}\ \ \ \mbox{and} \ \ \ (c_k^g (p_k))'({\eta}_k)={\theta}_k^g ({\bar{t}}_k^g) \x \frac{1}{{\eta}_{k+1} - {\eta}_k}.
\]
This implies that $(c_k^f (p_k))'({\eta}_k)$ and $(c_k^g (p_k))'({\eta}_k)$ do not depend on $\al$. Moreover, it must hold that
\[
(c_k^f (p_k))'({\eta}_k) < (c_k^g (p_k))'({\eta}_k);
\]
else, if
\[
(c_k^f (p_k))'({\eta}_k) \geq (c_k^g (p_k))'({\eta}_k),
\]
then, we would obtain
\[
\frac{{\bar{y}}_{k+1}^f - {\bar{y}}_k^f}{{\eta}_{k+1} - {\eta}_k} \leq \frac{{\bar{y}}_{k+1}^g - {\bar{y}}_k^g }{{\eta}_{k+1} - {\eta}_k}.
\]
Applying step \ref{itemAlgoOne}.\ref{alg1:actionOne}), this would imply
\[
{\bar{y}}_{k+1}^f \leq {\bar{y}}_{k+1}^g.
\]
However, by step \ref{itemAlgoFour}.\ref{alg4:actC}), we know that
\[
{\bar{y}}_{k+1}^f > {\bar{y}}_{k+1}^g,
\]
which leads to a contradiction.

In case ${\bar{t}}_k^f = {\bar{t}}_k^g$ we have four subcases, namely $(c_k^f (p_k))'({\eta}_k) >0$ and $(c_k^g (p_k))'({\eta}_k) >0$; $(c_k^f (p_k))'({\eta}_k) <0$ and $(c_k^g (p_k))'({\eta}_k) <0$; $(c_k^f (p_k))'({\eta}_k) < 0$ and $(c_k^g (p_k))'({\eta}_k) \geq 0$; and finally, $(c_k^f (p_k))'({\eta}_k) \leq 0$ and $(c_k^g (p_k))'({\eta}_k) >0$. We consider the first one, whereas the others have a similar proof.

If $(c_k^f (p_k))'({\eta}_k) >0$ and $(c_k^g (p_k))'({\eta}_k) >0$, then
\[
{\theta}_k^f ({\bar{t}}_k^f) = ({\eta}_{k+1} - {\eta}_k ) \x ( c_k^f (p_k))'({\eta}_k) > 0
\]
and
\[
{\theta}_k^g ({\bar{t}}_k^g) = ({\eta}_{k+1} - {\eta}_k ) \x ( c_k^g (p_k))'({\eta}_k) > 0,
\]
besides, because of $(c_k^f (p_k))'({\eta}_k) < (c_k^g (p_k))'({\eta}_k)$, we have ${\theta}_k^f ({\bar{t}}_k^f) < {\theta}_k^g ({\bar{t}}_k^g)$. From definitions and properties of \Subsec{subsec:tools} we can compute the following second derivative:
\[
(c_k^f)''(0)= \left\{
\begin{array}{ll}
-({\theta}_k^f ({\bar{t}}_k^f))^2 \x \frac{1}{\al} + 8\al & \mbox{if}\ c_k^f\ \mbox{is single},\\[1pt]
-({\theta}_k^f ({\bar{t}}_k^f))^2 \x \frac{1}{\al} + 32\al & \mbox{if}\ c_k^f\ \mbox{is double or special},
\end{array}
\right.
\]
and
\[
(c_k^g)''(0)= \left\{
\begin{array}{ll}
-({\theta}_k^g ({\bar{t}}_k^g))^2 \x \frac{1}{\al} + 8\al & \mbox{if}\ c_k^g\ \mbox{is single},\\[1pt]
-({\theta}_k^g ({\bar{t}}_k^g))^2 \x \frac{1}{\al} + 32\al & \mbox{if}\ c_k^g\ \mbox{is double or special}.
\end{array}
\right.
\]
Then, for $\al $ sufficiently small, we have:
\begin{align*}
&(s_k^f (p_k) +c_k^f (p_k))''({\eta}_k) - (s_k^g (p_k) + c_k^g (p_k) )''({\eta}_k) \\
& \quad = \textstyle {\left( \frac{1}{{\eta}_{k+1} -{\eta}_k} \right)}^2 \x (c_k^f)''(p_k({\eta}_k)) - {\left( \frac{1}{{\eta}_{k+1} - {\eta}_k} \right) }^2 \x (c_k^g)''(p_k({\eta}_k))\\
& \quad = \textstyle {\left( \frac{1}{{\eta}_{k+1} - {\eta}_k } \right) }^2 \x (c_k^f)''(0) - {\left( \frac{1}{{\eta}_{k+1} - {\eta}_k} \right) }^2 \x (c_k^g)''(0) >0
\end{align*}
thus, by \Lem{lem:1.13}, for $\al$ sufficiently small it exists $\bar{\eta} \! \in ]{\eta}_k, {\eta}_{k+1}]$ such that:
\[
s_k^f (p_k(\eta )) + c_k^f (p_k(\eta )) > s_k^g (p_k(\eta )) + c_k^g (p_k(\eta ))\ \ \ \forall \eta \in ]{\eta}_k , \bar{\eta} ]
\]
and 
\[
(Mf)_{\al}(\eta ) > (Mg)_{\al} (\eta ) \ \ \ \forall \eta \in ]{\eta}_k , \bar{\eta} ].  \tag*{\qed}
\]

We can summarize the two preceding propositions as the following properties:
\[
\begin{array}{ll}
\mbox{\Prop{prop:2.3}} & \forall \bar{\eta} \! \in ]{\eta}_k , {\eta}_{k+1}]\ \exists {\al}_{\bar{\eta}} : \forall \al \in \I , \al < {\al}_{\bar{\eta}} \imp (Mf)_{\al} > (Mg)_{\al}\ \mbox{in} \ ] \bar{\eta} , {\eta}_{k+1}]; \\[0.1cm]
\mbox{\Prop{prop:2.4}} & \forall \tilde{\al} \! \in \! \I \ \exists {\eta}_{\tilde{\al}} : (Mf)_{\tilde{\al}} > (Mg)_{\tilde{\al}} \ \mbox{in} \ ]{\eta}_k , {\eta}_{\tilde{\al}}].
\end{array}
\] 
Let us go back to our problem and let $M$ be a model with ${\al}^* \! \in \! \I$. By \Prop{prop:2.4} we have:
\[
\exists {\eta}_{{\al}^*}={\eta}^* \in ]{\eta}_k , {\eta}_{k+1}]\ \mbox{such that}\ (Mf)_{{\al}^*} > (Mg)_{{\al}^*}\ \mbox{in}\ ]{\eta}_k , {\eta}^* ];
\]
now, ${\eta}^* \in ] {\eta}_k , {\eta}_{k+1}]$, thus, by \Prop{prop:2.3} we have:
\[
\exists {\al}_{{\eta}^*} = \hat{\al} \ \mbox{such that}\ \forall \al \in \I , \al < \hat{\al} \imp (Mf)_{\al} > (Mg)_{\al} \ \mbox{in}\ ]{\eta}^* , {\eta}_{k+1}], 
\]
if ${\al}^* \! < \! \hat{\al}$ then we have $(Mf)_{{\al}^*} > (Mg)_{{\al}^*}$ in $]{\eta}_k , {\eta}_{k+1}]$ and we are done.

It remains the possibility that ${\al}^* \geq \hat{\al}$.

In this case, let $\bar{\eta} \in ]{\eta}_k , {\eta}^*]$ with $\bar{\eta} < {\eta}_k + \frac{{\eta}_{k+1} - {\eta}_k}{4}$, then by \Prop{prop:2.3}:
\[
\exists {\al}_{\bar{\eta}} = \bar{\al}\ \mbox{such that} \ \forall \al \in \I , \al < \bar{\al} \imp (Mf)_{\al} > (Mg)_{\al} \ \mbox{in} \ ]\bar{\eta} , {\eta}_{k+1}].
\]
Let now $\tilde{\al} \in \I $ with $\tilde{\al} < \bar{\al}$ and $\tilde{\al} < {\al}^*$, then by \Prop{prop:2.4} we have:
\[
\exists {\eta}_{\tilde{\al}}= \tilde{\eta} \in ]{\eta}_k ,{\eta}_{k+1}]\ \mbox{such that}\ (Mf)_{\tilde{\al}} > (Mg)_{\tilde{\al}} \ \mbox{in}\ ]{\eta}_k , \tilde{\eta}],
\]
and, because $\tilde{\al} < \bar{\al}$, we also have $(Mf)_{\tilde{\al}} > (Mg)_{\tilde{\al}}$ in $[\bar{\eta} , {\eta}_{k+1}]$; thus:
\[
(Mf)_{\tilde{\al}} > (Mg)_{\tilde{\al}}\ \mbox{in}\ ]{\eta}_k , \tilde{\eta}] \cup [\bar{\eta} , {\eta}_{k+1}],
\]
it remains to prove the property inside the interval $[\tilde{\eta} , \bar{\eta}]$.

Let us consider the functions $S^h(\eta) \putAs s^h_k(p_k(\eta))$ and $C^h_{\al}(\eta) \putAs c^h_{k,\al}(p_k(\eta))$ where $c^h_{k,\al}$ is the $[\al, \theta^h_k(\bar{t}^h_k),\theta^h_k(\bar{t}^h_{k+1})]$-defined function, with $\al \! \in  ]0,\al^*]$ and $h \! \in \! \{f,g\}$.

Then, we may decompose the functions $(Mf)_{{\al}^*}$ and $(Mg)_{{\al}^*}$ as:
\[
(Mf)_{{\al}^*} = S^f + C_{{\al}^*}^f \ \ \mbox{and}\ \ (Mg)_{{\al}^*} = S^g + C_{{\al}^*}^g\ \ \mbox{in}\ \ [{\eta}_k , {\eta}_{k+1}]
\]
where $S^f$ and $S^g$ are the interpolating linear functions between the points $({\eta}_k , {\bar{y}}_k^f), ({\eta}_{k+1} ,{\bar{y}}_{k+1}^f)$ and $({\eta}_k , {\bar{y}}_k^g), ({\eta}_{k+1}, {\bar{y}}_{k+1}^g)$ (with ${\bar{y}}_k^f = {\bar{y}}_f^g$ and ${\bar{y}}_{k+1}^f > {\bar{y}}_{k+1}^g$), while $C_{{\al}^*}^f$ and $C_{{\al}^*}^g$ are $[\al , {\theta}_1 , {\theta}_2]$-defined functions rescaled from $[0,1]$ to $[{\eta}_k , {\eta}_{k+1}]$, with $\theta$s defined by the derivative conditions at the endpoints.

Since $\bar{\eta} \in ]{\eta}_k , {\eta}^* ]$ and ${\bar{y}}_{k+1}^f > {\bar{y}}_{k+1}^g$, we have:
\[
(Mf)_{{\al}^*} > (Mg)_{{\al}^*}\ \ \mbox{and} \ \ S^f > S^g \ \ \mbox{in}\ \ [\tilde{\eta} , \bar{\eta}].
\] 
We now consider $(Mf)_{\tilde{\al}}$ and $(Mg)_{\tilde{\al}}$, they have the following form:
\[
(Mf)_{\tilde{\al}} = S^f + C_{\tilde{\al}}^f\ \ \mbox{and} \ \ (Mg)_{\tilde{\al}} = S^g + C_{\tilde{\al}}^g \ \ \mbox{in}\ \ [\eta_k , \eta_{k+1}],
\]
let us denote ${\theta}_1^f \putAs(C_{{\al}^*}^f)'({\eta}_k)=(C_{\tilde{\al}}^f)'({\eta}_k)$ and ${\theta}_1^g \putAs(C_{{\al}^*}^g)'({\eta}_k)=(C_{\tilde{\al}}^g)'({\eta}_k)$. Since $\tilde{\al} \! < \! {\al}^*$, by \Lem{lem:1.9} we also have $|C_{\tilde{\al}}^f| \! < \! |C_{{\al}^*}^f|$ and $|C_{\tilde{\al}}^g| \! < \! |C_{{\al}^*}^g|$.

\smallskip

Let $\eta_0 \in [\tilde{\eta} , \bar{\eta}]$, we have five possibilities, depending on ${\theta}_1^f$ and ${\theta}_1^g$. The first three of these five sub-cases are rather straightforward; whereas the last two require more attention.

1) ${\theta}_1^f=0$ or ${\theta}_1^g=0$, in this case $(Mf)_{{\al}^*}(\eta_0)=S^f(\eta_0)$ or $(Mg)_{{\al}^*}(\eta_0)=S^g(\eta_0)$ in $[\tilde{\eta},\bar{\eta}]$, for the first one we have:
\[
 (Mg)_{\tilde{\al}}(\eta_0) \leq \max\{(Mg)_{{\al}^*}(\eta_0), S^g(\eta_0)\} < (Mf)_{{\al}^*}(\eta_0)=S^f(\eta_0)=(Mf)_{\tilde{\al}}(\eta_0)
\]
thus $ (Mg)_{\tilde{\al}}(\eta_0)<(Mf)_{\tilde{\al}}(\eta_0)$; the other case is similar.

2) ${\theta}_1^f<0$ and ${\theta}_1^g>0$, here $(Mf)_{{\al}^*}(\eta_0)<S^f(\eta_0)$ and $(Mg)_{{\al}^*}(\eta_0)>S^g(\eta_0)$ in $[\tilde{\eta},\bar{\eta}]$, so we have
\[
S^g(\eta_0)<(Mg)_{\tilde{\al}}(\eta_0)<(Mg)_{{\al}^*}(\eta_0)<(Mf)_{{\al}^*}(\eta_0)<(Mf)_{\tilde{\al}}(\eta_0)<S^f(\eta_0)
\]
thus $ (Mg)_{\tilde{\al}}(\eta_0)<(Mf)_{\tilde{\al}}(\eta_0)$. 

3) ${\theta}_1^f>0$ and ${\theta}_1^g<0$, in this case we obtain $(Mf)_{{\al}^*}(\eta_0)>S^f(\eta_0)$ and $(Mg)_{{\al}^*}(\eta_0)<S^g(\eta_0)$ in $[\tilde{\eta},\bar{\eta}]$, therefore:
\[
(Mg)_{{\al}^*}(\eta_0)<(Mg)_{\tilde{\al}}(\eta_0)<S^g(\eta_0)<S^f(\eta_0)<(Mf)_{\tilde{\al}}(\eta_0)<(Mf)_{{\al}^*}(\eta_0)
\]
and thus $ (Mg)_{\tilde{\al}}(\eta_0)<(Mf)_{\tilde{\al}}(\eta_0)$.

4-5) Of the two remaining cases, namely ${\theta}_1^f>0,\ {\theta}_1^g>0$ and ${\theta}_1^f<0,\ {\theta}_1^g<0$, we consider only the former, as the treatment of the other case is strictly analogous.

Since the only interval under consideration is $[\eta_k,\eta_{k+1}]$, in the following we omit the index $k$ for functions, e.g. $s^f$ instead of $s^f_k$; on the other hand, given its relevance inside the proof, we keep the appropriate index $\al$ for the $[\al,\theta_1,\theta_2]$-defined functions involved, e.g. $c^f_{\tilde{\al}}$. Thus, by definition, we have:
\[
(Mf)_{\tilde{\al}}(\eta) = s^f(p(\eta))+c_{\tilde{\al}}^f(p(\eta))\ \ \mbox{and}\ \ (Mg)_{\tilde{\al}}(\eta) = s^g(p(\eta))+c_{\tilde{\al}}^g(p(\eta))\ \ \mbox{in}\ \ [{\eta}_k,{\eta}_{k+1}],
\]
where
\[
 p \colon [{\eta}_k,{\eta}_{k+1}] \frec [0,1]\ \ \mbox{with}\ \  p(\eta) = \frac{\eta -{\eta}_k}{{\eta}_{k+1}-{\eta}_k},
\]
and
\[
s^h\colon [0,1]\frec \mR\ \ \mbox{with}\ \ s^h(x)={\bar{y}}_k^h+({\bar{y}}_{k+1}^h-{\bar{y}}_k^h)\x x,\ \ h\! \in \{ f,g \}.
\]
Then
\begin{align*}
(Mf)_{\tilde{\al}}(\eta) >(Mg)_{\tilde{\al}}(\eta) \ \mbox{in}\  [\tilde{\eta}, \bar{\eta}] & 
~~\Longleftrightarrow~~ s^f(p(\eta))+c_{\tilde{\al}}^f(p(\eta)) > s^g(p(\eta))+c_{\tilde{\al}}^g(p(\eta)) \ \mbox{in} \ [\tilde{\eta}, \bar{\eta}] \\
%& ~~\Longleftrightarrow~~  (Mf)_{\tilde{\al}}(x) >(Mg)_{\tilde{\al}}(x) \ \mbox{in}\  [\tilde{x}, \bar{x}]\\ %\mbox{con}\ \bar{x}<\frac{1}{4}
& ~~\Longleftrightarrow~~ s^f(x)+c_{\tilde{\al}}^f(x)>s^g(x)+c_{\tilde{\al}}^g(x) \ \mbox{in}\  [\tilde{x}, \bar{x}] \\ 
& ~~\Longleftrightarrow~~ c_{\tilde{\al}}^f(x)+L(x)>c_{\tilde{\al}}^g(x) \ \mbox{in}\  [\tilde{x}, \bar{x}],
\end{align*}
where $\tilde{x}$ and $\bar{x}$ are the projection through $p$ of $\tilde{\eta}$ and $\bar{\eta}$, and $L(x)=k\x x=s^f(x)-s^g(x)$ with $k>0$ a real number; in particular, $L(x) \geq 0$ in $[0,1]$ and $0 <\bar{x}<\frac{1}{4}$.

Moreover, because
\[
(Mf)_{\tilde{\al}}(\eta)>(Mg)_{\tilde{\al}}(\eta)\ \mbox{in}\ ]{\eta}_k,\tilde{\eta}]\cup [\bar{\eta},{\eta}_{k+1}]
\]
we have
\[
(Mf)_{\tilde{\al}}(\tilde{\eta})>(Mg)_{\tilde{\al}}(\tilde{\eta})\ \mbox{and}\ (Mf)_{\tilde{\al}}(\bar{\eta})>(Mg)_{\tilde{\al}}(\bar{\eta})\
\]
thus, with a slight abuse of notation,
\[
(Mf)_{\tilde{\al}}(\tilde{x})>(Mg)_{\tilde{\al}}(\tilde{x})\ \mbox{and}\ (Mf)_{\tilde{\al}}(\bar{x})>(Mg)_{\tilde{\al}}(\bar{x}).\
\]
We now consider three cases, depending on the type (single, double or special) of functions $c^f_{\tilde{\al}}$ and $c^g_{\tilde{\al}}$.

Since in the following the focus shifts from the functions $C^f_{\tilde{\al}}$ and $C^g_{\tilde{\al}}$ to $c^f_{\tilde{\al}}$ and $c^g_{\tilde{\al}}$, let us define $\theta^h \putAs \left( c^h_{\tilde{\al}}\right)'(0)\ \mbox{with} \ h \in \{ f,g \}$, observing that $\theta^h_1 = \left( C^h_{\tilde{\al}}\right)'(\eta_k)=\left( c^h_{\tilde{\al}}\right(p))'(\eta_k)=\left( c^h_{\tilde{\al}}\right)'(p(\eta_k)) \x p'(\eta_k)=\theta^h \x \frac{1}{\eta_{k+1}-\eta_k}$; in particular, $\theta^h > 0 \Leftrightarrow \theta^h_1 > 0$ and $\theta^f \bowtie \theta^g \Leftrightarrow \theta^f_1 \bowtie \theta^g_1$ with ${\bowtie} \in \{ <,\leq,=,\geq,>\}$.

\bigskip

\centerline{\fbox{\texttt{First case: $c^f_{\tilde{\al}}$ and $c^g_{\tilde{\al}}$ of the same type}}}

We assume that both $c_{\tilde{\al}}^f$ and $c_{\tilde{\al}}^g$ are single-defined. By definition, and because $[\tilde{x}, \bar{x}] \subset ]0, \frac{1}{4}[$, we have:
\begin{align*}
 c_{\tilde{\al}}^f(x)+L(x)> c_{\tilde{\al}}^g(x)  & ~~\Longleftrightarrow~~
\tilde{\al} [ 1-(2x-1)^2 e^{-2 \left( \frac{{\theta}^f}{2\tilde{\al}}-2 \right) x} ] +k\x x  > \tilde{\al}[ 1-(2x-1)^2 e^{-2\left( \frac{{\theta}^g}{2\tilde{\al}}-2\right)x} ] \\
& ~~\Longleftrightarrow~~ \tilde{\al} [ 1-(2x-1)^2 e^{- \frac{{\theta}^f}{\tilde{\al}}x+4x} - 1 +(2x-1)^2 e^{- \frac{{\theta}^g}{\tilde{\al}}x+4x} ] > -k\x x \\
& ~~\Longleftrightarrow~~ (2x-1)^2 e^{4x} [ -e^{- \frac{{\theta}^f}{\tilde{\al}}x}+e^{- \frac{{\theta}^g}{\tilde{\al}}x} ]>  -\Kappa \x x \\
& \textstyle ~~\Longleftrightarrow~~ e^{-Gx}-e^{-Fx}> -\frac{\Kappa\,x}{e^{4x} (2x-1)^2}\\
& \textstyle ~~\Longleftrightarrow~~ \frac{\Kappa\,x}{e^{4x} (2x-1)^2} > e^{-Fx}-e^{-Gx},     
\end{align*}
where $\Kappa=\frac{k}{\tilde{\al}}>0$, $F=\frac{{\theta}^f}{\tilde{\al}}>0$, and $G=\frac{{\theta}^g}{\tilde{\al}}>0$.

We consider the functions:
\[
FG(x) \putAs e^{-Fx}-e^{-Gx}\ \ \mbox{and}\ \ K(x) \putAs \frac{\Kappa\,x}{e^{4x} (2x-1)^2}\ \mbox{in}\ \left[ 0,\frac{1}{4} \right],
\]
for which we have:
\[
FG(0)=K(0)=0\ \ \mbox{and}\ \ K(x)=\frac{\Kappa\,x}{e^{4x} (2x-1)^2}>0\ \mbox{in}\ \left] 0, \frac{1}{4} \right].
\]

We consider two sub-cases:

\noindent {\bf\boldmath($ {\theta}^g \leq {\theta}^f $):}\ If $0<{\theta}^g \leq {\theta}^f$ then $0<G\leq F$, thus $e^{-Gx}\geq e^{-Fx}$ in $[0,\frac{1}{4}]$, therefore $e^{-Fx} - e^{-Gx}\leq 0< K(x)$, whence the sought conclusion $(Mf)_{\tilde{\al}}(\eta)>(Mg)_{\tilde{\al}}(\eta)$  follows for all $\eta\in [\tilde{\eta},\bar{\eta}]$.
%It remains the case $0<{\theta}^f<{\theta}^g$.

\noindent {\bf\boldmath($ {\theta}^f < {\theta}^g $):}\ Let us study $K(x)$. We have:
\begin{align*}
K'(x) & =  \Kappa\frac{e^{4x}(2x-1)^2-x[4e^{4x}(2x-1)^2+4(2x-1)e^{4x}]}{[e^{4x}(2x-1)^2]^2}\\
      & =  \Kappa\frac{2x-1-8x^2}{e^{4x} (2x-1)^3}
\end{align*}
thus, $K'(0)=\Kappa$ and $K'(x)>0$ in $[0,\frac{1}{4}]$.
\begin{align*}
K''(x) & =  \Kappa\frac{(2-16x)e^{4x}(2x-1)^3-(2x-1-8x^2)[4e^{4x}(2x-1)^3+6e^{4x}(2x-1)^2]}{[e^{4x}(2x-1)^3]^2]} \\
       & =  \Kappa\frac{(2-16x)(2x-1)-(2x-1-8x^2)[4(2x-1)+6]}{e^{4x}(2x-1)^4} \\
       & =  8\Kappa\frac{8x^3+3x-4x^2}{e^{4x}(2x-1)^4}\ =\ 8\Kappa\frac{x(8x^2-4x+3)}{e^{4x}(2x-1)^4}
\end{align*}
thus, $K''(0)=0$ and $K''(x)>0$ in $]0,\frac{1}{4}]$, therefore in $[0,\frac{1}{4}]\ K(x)$ is an  \ita{increasing} and \ita{convex} function.

Now we study $FG(x)$. $0 \! < \! {\theta}^f \! < \! {\theta}^g$ implies that $0 \! < \! F \! < \! G$, thus $e^{-Fx}>e^{-Gx}$ and therefore $FG(x)>0$ in $[0,\frac{1}{4}]$; moreover:
\begin{align*}
    FG'(x) & =Ge^{-Gx}-Fe^{-Fx},~ \text{with } FG'(0)=G-F>0,
    \intertext{and}
    FG''(x) &=F^2 e^{-Fx}-G^2 e^{-Gx},~ \text{with } FG''(0)=F^2-G^2<0.
\end{align*}

In particular, after some trivial computation we obtain:
\begin{align*}
    FG'(x) > 0 & \Longleftrightarrow  e^{\frac{x}{\tilde{\al}}(\theta^g- \theta^f)} < \frac{\theta^g}{\theta^f},
    \intertext{and}
    FG''(x) > 0 & \Longleftrightarrow  e^{\frac{x}{\tilde{\al}}(\theta^g- \theta^f)} > \left(\frac{\theta^g}{\theta^f}\right)^{\! 2}.
\end{align*}

Since $\left(\frac{\theta^g}{\theta^f}\right)^{\! 2} > \frac{\theta^g}{\theta^f}$ (because $\theta^g > \theta^f$ and thus $\frac{\theta^g}{\theta^f} >1$), if $FG(x)$ is increasing, then it is concave; and since $FG(0)>0$ there exists $\be >0$ such that $FG(x)$ is increasing, and concave, in $[0,\be]$. There are three possibilities $\be \in ]0,\tilde{x}]$, $\be \in ]\tilde{x}, \bar{x}[$ or $\be \geq \bar{x}$; we consider only the second one, being the other two treatable in an analogous way. 

We know that $K(x) \! > \! FG(x)$ in $]0,\tilde{x}] \cup [\bar{x},1]$, with $0 < \tilde{x} < \be < \bar{x} < \frac{1}{4}$.
\begin{enumerate}

\item let us consider the point $\tilde{X}=(\tilde{x},K(\tilde{x}))$, with $K(\tilde{x})>FG(\tilde{x})$, and the line $r$ passing through the origin $(0,0)$ and the point $\tilde{X}$. In $[0,\be]$ functions $\Kappa$ and $FG$ are both increasing and, respectively, convex and concave; thus, in the interval $[\tilde{x},\be]$ the function $\Kappa$ will be above the line $r$, while $FG$ will be below it, and so $K(x) > FG(x)$ in $[\tilde{x},\be]$.

\item from the previous point we have $\Kappa(\be) > FG(\be)$; since in $[\be, \bar{x}]$ $\Kappa$ is increasing whereas $FG$ is decreasing, we obtain $\Kappa(x) > FG(x)$ also in $[\be,\bar{x}]$.

\end{enumerate}

Therefore, we have:
\[
\forall x\! \in \! [\tilde{x},\bar{x}]\ K(x)>FG(x) \imp (Mf)_{\tilde{\al}}(x) \! > \! (Mg)_{\tilde{\al}}(x)\imp (Mf)_{\tilde{\al}}(\eta) > (Mg)_{\tilde{\al}}(\eta)\ \mbox{in}\ [\tilde{\eta},\bar{\eta}].
\]
If both $c_{\tilde{\al}}^f$ and $c_{\tilde{\al}}^g$ are double- or special-defined the proof is completely analogous.

\bigskip

\centerline{\fbox{\texttt{Second case: $c^f_{\tilde{\al}}$ double- or special-defined and $c^g_{\tilde{\al}}$ single-defined}}}
%\subsubsection*{Second case: $C^f_{\tilde{\al}}$ double- or special-defined and $C^g_{\tilde{\al}}$ single-defined.\\ }
%Let's look at the case in which $C_{\tilde{\al}}^f$ is double or special and $C_{\tilde{\al}}^g$ single-defined.
For this case, in $[0,\frac{1}{4}]$ we have:
\begin{align*}
 c_{\tilde{\al}}^f(x)+L(x)> c_{\tilde{\al}}^g(x) &~~\Longleftrightarrow~~ \tilde{\al} [ 1-(4x-1)^2 e^{-2 \left( \frac{{\theta}^f}{4\tilde{\al}}-2 \right) 2x} ] +k\x x  > \tilde{\al}[ 1-(2x-1)^2 e^{-2\left( \frac{{\theta}^g}{2\tilde{\al}}-2\right)x} ] \\
&~~\Longleftrightarrow~~ \tilde{\al} [ 1-(4x-1)^2 e^{- \frac{{\theta}^f}{\tilde{\al}}+8x} - 1 +(2x-1)^2 e^{- \frac{{\theta}^f}{2\tilde{\al}}+4x} ] > -k\x x \\
&\textstyle ~~\Longleftrightarrow~~ (2x-1)^2 e^{4x} [ -\left(\frac{4x-1}{2x-1}\right)^2 e^{- \frac{{\theta}^f}{\tilde{\al}}x+4x}+e^{- \frac{{\theta}^g}{\tilde{\al}}x} ]>  -\Kappa \x x \\
&\textstyle ~~\Longleftrightarrow~~ e^{-Gx}-\left(\frac{4x-1}{2x-1}\right)^2 e^{-Fx}> -\frac{\Kappa\,x}{e^{4x} (2x-1)^2}\\
&\textstyle ~~\Longleftrightarrow~~ \frac{\Kappa\,x}{e^{4x} (2x-1)^2} > \left(\frac{4x-1}{2x-1}\right)^2 e^{-Fx}-e^{-Gx},
\end{align*}
where $\Kappa=\frac{k}{\tilde{\al}}>0$, $F=\frac{{\theta}^f}{\tilde{\al}}-4>0$, and $G=\frac{{\theta}^g}{\tilde{\al}}>0$.\\
Thus, we have in $[0,\frac{1}{4}]$:
\[
\textstyle \frac{4x-1}{2x-1} \! \leq \! 1 \! \imp  \! {\left( \frac{4x-1}{2x-1}\right)}^2 \! \! \! \leq \! 1 \! \imp \! \! \left( \frac{4x-1}{2x-1} \right)^2 \! \! e^{-Fx} \! \leq \! e^{-Fx} \imp \! \left( \frac{4x-1}{2x-1} \right)^2 \! \! e^{-Fx}-e^{-Gx} \! \leq \! e^{-Fx}-e^{-Gx}
\]
therefore:
\[
\textstyle \frac{\Kappa\,x}{e^{4x} (2x-1)^2} > e^{-Fx}-e^{-Gx} \geq \left( \frac{4x-1}{2x-1}\right)^2 e^{-Fx}-e^{-Gx} \ \mbox{in}\ [\tilde{x}, \bar{x}],
\]
where the first inequality comes from the single-single case treated before.

\bigskip

\centerline{\fbox{\texttt{Third case: $c^f_{\tilde{\al}}$ single-defined and $c^g_{\tilde{\al}}$ double- or special-defined}}}

%Finally, we consider the last case, where $C_{\tilde{\al}}^f$ is single-defined, while $C_{\tilde{\al}}^g$ is double or special-defined.
As before, we consider the interval $[0,\frac{1}{4}]$ and we have:
\begin{align*}
 c_{\tilde{\al}}^f(x)+L(x)> c_{\tilde{\al}}^g(x)& ~~\Longleftrightarrow~~ \tilde{\al} [ 1-(2x-1)^2 e^{-2 \left( \frac{{\theta}^f}{2\tilde{\al}}-2 \right) x} ] +k\x x  > \tilde{\al}[ 1-(4x-1)^2 e^{-2\left( \frac{{\theta}^g}{4\tilde{\al}}-2\right) 2x} ] \\
& ~~\Longleftrightarrow~~ \tilde{\al} [ 1-(2x-1)^2 e^{- \frac{{\theta}^f}{\tilde{\al}}x+4x} - 1 +(2x-1)^2 e^{- \frac{{\theta}^g}{\tilde{\al}}x+8x} ] > -k\x x \\
&\textstyle ~~\Longleftrightarrow~~ (2x-1)^2 e^{4x} [ -e^{- \frac{{\theta}^f}{\tilde{\al}}x}+ \left(\frac{4x-1}{2x-1}\right)^2e^{- \frac{{\theta}^g}{\tilde{\al}}x+4x} ]>  -\Kappa \x x \\
&\textstyle ~~\Longleftrightarrow~~ \left(\frac{4x-1}{2x-1}\right)^2e^{-Gx}-e^{-Fx}> -\frac{\Kappa\,x}{e^{4x} (2x-1)^2}\\
&\textstyle ~~\Longleftrightarrow~~ \Kappa\frac{x}{e^{4x} (2x-1)^2} >  e^{-Fx}-(\frac{4x-1}{2x-1})^2e^{-Gx} ,
\end{align*}
with $\Kappa=\frac{k}{\tilde{\al}}>0$, $F=\frac{{\theta}^f}{\tilde{\al}}>0$, and $G=\frac{{\theta}^g}{\tilde{\al}}-4>0$.

We consider:
\[
K(x) \putAs\Kappa\frac{x}{e^{4x} (2x-1)^2}\ \ \mbox{and}\ \ FG(x)\putAs e^{-Fx}-\left( \frac{4x-1}{2x-1}\right)^{\! 2} e^{-Gx}.
\]
As before, $K(x)$ is increasing and convex in $[0,\frac{1}{4}]$.

For $FG(x)$, we have:
\begin{align*}
FG'(x) & \textstyle =  -Fe^{-Fx}-\left[ -Ge^{-Gx} \x \left( \frac{4x-1}{2x-1} \right)^{\! 2} + e^{-Gx} \x 2 \x \left( \frac{4x-1}{2x-1}\right) \x \frac{4(2x-1)-2(4x-1)}{(2x-1)^2} \right] \\[0.25cm]
 & \textstyle =  -Fe^{-Fx}-\left[ -Ge^{-Gx}\left( \frac{4x-1}{2x-1} \right)^{\! 2} - e^{-Gx} \left( \frac{4x-1}{2x-1} \right) \frac{4}{(2x-1)^2} \right] \\
 & \textstyle =  -Fe^{-Fx}+e^{-Gx}\left[ \left( \frac{4x-1}{2x-1} \right)^{\! 2} G +4\frac{4x-1}{(2x-1)^3} \right]
\end{align*}
and, in particular,
\[
\textstyle FG'(0)=-F+G+4=-\frac{{\theta}^f}{\tilde{\al}}+\frac{{\theta}^g}{\tilde{\al}}-4+4=\frac{{\theta}^g-{\theta}^f}{\tilde{\al}}\ \ \mbox{and}\ \ FG'\left (\textstyle{\frac{1}{4}} \right) <0.
\]
As for the second derivative, we have:
\begin{align*}
FG''(x) & = \textstyle  F^2 e^{-Fx} + \left\{  -Ge^{-Gx}  \x   \left[  \left( \frac{4x-1}{2x-1} \right)^2  G + 4\frac{4x-1}{(2x-1)^3}  \right] + \right.  \\
 & \textstyle  \hspace{2.6cm}  + \, e^{-Gx} \left[ 2G  \left( \frac{4x-1}{2x-1} \right)  \x  \frac{-2}{(2x-1)^2}   + 4  \frac{8x-4-6(4x-1)}{(2x-1)^4} \right]  \bigg\} \\
 & =  \textstyle  F^2e^{-Fx}+\left\{-Ge^{-Gx}  \x  \left[ \! \left( \frac{4x-1}{2x-1} \right)^2 \! G\! +\! 4\frac{4x-1}{(2x-1)^3} \! \right] \! +e^{-Gx} \left[-4G\frac{4x-1}{(2x-1)^3}+8\frac{1-8x}{(2x-1)^4} \right] \right\} \\
 & = \textstyle  F^2e^{-Fx}+e^{-Gx} \left[ -G^2\left( \frac{4x-1}{2x-1}\right)^2 -4G\frac{4x-1}{(2x-1)^3}-4G\frac{4x-1}{(2x-1)^3}+8\frac{1-8x}{(2x-1)^4} \right]\\[0.25cm]
 & = \textstyle  F^2e^{-Fx}-e^{-Gx}\left[ G^2 \left( \frac{4x-1}{2x-1}\right)^2 + 8G\frac{4x-1}{(2x-1)^3}-8\frac{1-8x}{(2x-1)^4} \right]
\end{align*}
and, in particular,
\[
\textstyle FG''(0)=F^2-[G^2+8G-8]=F^2-[(G+4)^2-24]= \! \left(\frac{{\theta}^f}{\tilde{\al}}\right)^2 \! -\left(\frac{{\theta}^g}{\tilde{\al}}\right)^2 \! +24=\frac{({\theta}^f)^2-({\theta}^g)^2}{{\tilde{\al}}^2} +24.
\]
The previous computations can be extended to the generic case with $0 < \al \leq \al$. More precisely, we can consider the parameters $\Kappa_{\al}=\frac{k}{\al}, F_{\al}=\frac{\theta^f}{\al},G_{\al}=\frac{\theta^g}{\al}-4$, and the functions
\[
K_{\al}(x) \putAs\Kappa_{\al}\frac{x}{e^{4x} (2x-1)^2}\ \ \mbox{and}\ \ FG_{\al}(x)\putAs e^{-F_{\al}x}-\left( \frac{4x-1}{2x-1}\right)^{\! 2} e^{-G_{\al}x}. 
\]
We also have the corresponding results for what concerns derivatives, namely:
\[
K_{\al}'(0)=\Kappa_{\al},\ FG_{\al}'(0)=\frac{\theta^g-\theta^f}{\al},\ FG'_{\al}\! \left(\frac{1}{4}\right) <0\ \mbox{and}\ FG''_{\al}(0)=\frac{({\theta}^f)^2-({\theta}^g)^2}{{\al}^2} +24
\]
Regarding notation, we keep the unlabelled case for $\al=\tilde{\al}$, e.g. $K(x)=K_{\tilde{\al}}(x)$.

As in the previous cases, our goal is to prove that, at least for $0  < \al \leq  \tilde{\al}$ sufficiently small, if
\[
K_{\al}(x)>FG_{\al}(x)\ \ \mbox{in}\ ]0,\tilde{x}] \cup \left[ \bar{x}, \textstyle{\frac{1}{4}} \right],
\]
then
\begin{equation} \tag{*}
\label{eqn:thesis}
K_{\al}(x)>FG_{\al}(x)\ \ \mbox{in}\ [\tilde{x}, \bar{x} ] .
\end{equation}
To this end, we distinguish the following three subcases, depending on the comparison between ${\theta}^g$ and ${\theta}^f$: 
\[
{\theta}^g = {\theta}^f, \qquad {\theta}^g < {\theta}^f, \qquad {\theta}^g > {\theta}^f.
\]

\bigskip

\centerline{\underline{\texttt{\boldmath$ {\theta}^g = {\theta}^f$}}}

Given the subcase hypothesis, previous expressions can be simplified, namely:
\begin{align*}
FG_{\al}(x) & \textstyle = e^{-\frac{{\theta}^f}{\al}x}-\left( \frac{4x-1}{2x-1}\right)^2 e^{-(\frac{{\theta}^f}{\al}-4)x} \\[0.1 cm]
 & \textstyle =  e^{-\frac{{\theta}^f}{\al}x}-\left( \frac{4x-1}{2x-1}\right)^2 e^{-\frac{{\theta}^f}{\al}x}\x e^{4x} \\[0.1 cm]
 & \textstyle =  e^{-\frac{\theta^f}{\al}x}\left[1-\left( \frac{4x-1}{2x-1}\right)^{\! 2}e^{4x} \right];
\end{align*}
in particular, we have $FG_{\al}(x)>0$ in $]0,\frac{1}{4}]$, $FG_{\al}'(0)=0$ and $FG_{\al}''(0) \geq 0$.

Let $x_0 \in ]0, \bar{x}]$ and $0 < \be < \al \leq \tilde{\al}$, from the expression of $FG_{\al}$, and the one for $K_{\al}(x)$, we can immediately derive the following properties:
\begin{itemize}

\item $\lim_{\al \frec 0^+} FG_{\al}(x_0)=0$,

\item $K_{\al}(x_0) < K_{\be}(x_0)$,

\item $FG_{\be}(x_0) < FG_{\al}(x_0)$.

\end{itemize}

Given these properties, for $\al$ sufficiently small we obtain:
\[
FG_{\al}(x) \leq \max_{\tau \in [\tilde{x}, \bar{x}]}FG_{\al}(\tau) < K_{\al}(\tilde{x}) \leq K_{\al}(x) \ \ \forall x \in [\tilde{x}, \bar{x}].
\]


\bigskip

\centerline{\underline{\texttt{\boldmath${\theta}^g < {\theta}^f$}}}

The treatment proceeds similarly as follows.

Since $FG'(0)<0$ and $FG(0) \! = \! 0$, there exists an $\be \! \in ]0,\frac{1}{4}]$ such that $FG(x) \! < \! 0$ in $]0,\be]$. If $\be > \bar{x}$ we are done; otherwise, we prove that $FG_{\al}(x)<0$ for all $\al \leq \tilde{\al}$ and all $x \in \, ]0,\be]$. This suffices to obtain $K_{\al} (x)> 0 > FG_{\al}(x)$ in $]0,\be]$; for what concerns $[\be, \bar{x}]$, we can rely on the same strategy used in the previous subcase $\theta^f = \theta^g$.

Given $x_0 \! \in ]0,\be]$, we consider $t \! = \! \frac{1}{\al}$, $\fhi \! = \! {\theta}^g x_0$, $\psi \! = \! {\theta}^f x_0$ and $A_{x_0}=\left(\frac{4x_0-1}{2x_0-1}\right)^2 e^{4x_0}$, with $\psi >\fhi $. 

From $FG_{\al}(x_0)=e^{-F_{\al}x_0}-\left( \frac{4x_0-1}{2x_0-1}\right)^{\! 2} e^{-G_{\al}x_0}$, we obtain by substitution the following function in $t$:
\[
E_{x_0}(t)=e^{-\psi t}-A_{x_0}e^{-\fhi t},
\]
and we consider its derivative
\[
E'_{x_0}(t)=-\psi e^{-\psi t}+\fhi A_{x_0} e^{-\fhi t}.
\]
In particular:
\[
\begin{array}{rclrcl}
E'_{x_0}(t) > 0   
& \Longleftrightarrow & -\psi e^{-\psi t} + \fhi A_{x_0} e^{-\fhi t} > 0 
& \Longleftrightarrow & \fhi A_{x_0} e^{-\fhi t}  > \psi e^{-\psi t} \\[1ex]
& \Longleftrightarrow &  e^{-\fhi t + \psi t}  > \dfrac{\psi}{\fhi} \cdot \dfrac{1}{A_{x_0}}
& \Longleftrightarrow & e^{(\psi - \fhi)t}  > \dfrac{\psi}{\fhi} \cdot \dfrac{1}{A_{x_0}}\/,
\end{array}
\]
with $\psi -\fhi > 0$.
Moreover, the following holds:
\[
\lim_{\al \to 0^+}FG_{\al}(x)=\lim_{t \to +\infty } E_{x}(t)=0\ \ \ \ \forall x \! \in \left[ 0,\frac{1}{4} \right] .
\]
Thus, given $x_0 \in ]0,\be]$ there are two possibilities:

\begin{enumerate}

\item the derivative $E'_{x_0}(t)$ is negative, hence $FG_{\al}(x_0)$ is decreasing, with respect to $\al \frec 0^+$, and still negative,
\item the derivative $E'_{x_0}(t)$ is positive, hence $FG_{\al}(x_0)$ is increasing with respect to $\al \frec 0^+$; but, since from that point the derivative will always be positive (while $t$ grows and $\al$ decreases) and $\lim_{t \to +\infty } E_{x_0}(t)=0$, $E_{x_0}(t)=FG_{\al}(x_0)$ will always be negative.

\end{enumerate}

Therefore, $K(x) \! > \! FG(x)$ holds in $]0,\be]$ for every $\al \! \leq \! \tilde{\al}$. As before, since $\lim_{\al \to 0^+ } FG_{\al}(x)=0$ also holds in $[\be, \bar{x}]$, for $\al$ sufficiently small we have:
\[
\textstyle K(x)>FG(x)\ \ \mbox{in}\ \ \left] 0,\frac{1}{4} \right],
\]
whence \eqref{eqn:thesis} follows.

\bigskip

\centerline{\underline{\texttt{\boldmath${\theta}^g > {\theta}^f$}}}

For the last case, we apply the same approach used in the case single-single. In particular, we prove that, at least for $\al$ sufficiently small, the two following properties hold:

\begin{enumerate}
\item $FG_{\al}'(0)>0$, $FG_{\al}'(\frac{1}{4})<0$, $FG_{\al}''(0)<0$ \mbox{and} $FG_{\al}''(\frac{1}{4})>0$,
\item $FG_{\al}$ has only one stationary tangent point, which is a maximum, and only one inflection point.
\end{enumerate}

If they hold, there exists a real value $\be \in ]0,\frac{1}{4}[$ such that $FG$ is increasing and concave in an interval $[0,\be]$ and decreasing in $[\be ,\frac{1}{4} ]$; then the proof is analogous to the single-single case. We now prove the two  properties.

Concerning the former, we have:
\[
\textstyle FG_{\al}'(0)= \frac{{\theta}^g -{\theta}^f}{\tilde{\al}} >0,\ \ \ FG_{\al}' \left( \frac{1}{4} \right)= -F_{\al}e^{-\frac{F_{\al}}{4}} < 0,
\]
and, for $\al$ sufficiently small,
\[
\textstyle FG_{\al}''(0)= \frac{({\theta}^f)^2 - ({\theta}^g)^2}{{\tilde{\al}}^2} + 24 <0,\ \ \ FG_{\al}'' \left( \frac{1}{4} \right) =  \frac{({\theta}^f)^2}{(\tilde{\al})^2}e^{-\frac{{\theta}^f}{4\tilde{\al}}} - 128e^{-\frac{{\theta}^g}{4\tilde{\al}} -1} > 0.
\]
As for the latter:
\begin{align*}
FG_{\al}'(x)=0 &~~ \textstyle \Longleftrightarrow ~~ F_{\al}e^{-F_{\al}x}=e^{-G_{\al}x}\left[ \left( \frac{4x-1}{2x-1}\right)^2 G_{\al}+4\frac{4x-1}{(2x-1)^3} \right] \\
&~~ \textstyle \Longleftrightarrow ~~ e^{(G_{\al}-F_{\al})x}= \frac{1}{F}\left[ \left( \frac{4x-1}{2x-1}\right)^2 G_{\al}+4\frac{4x-1}{(2x-1)^3} \right],
\end{align*}
thus, we consider the functions:
\[
\textstyle e^{(G_{\al}-F_{\al})x}\ \  \ \mbox{and}\  \ \ G_{F_{\al}} (x)=\frac{1}{F_{\al}}\left[ \left( \frac{4x-1}{2x-1} \right)^2 G_{\al}+4\frac{4x-1}{(2x-1)^3} \right] \ \mbox{in}\ \left[ 0,\frac{1}{4} \right].
\]
For $\al$ sufficiently small, the following holds:
\[
\textstyle G_{\al}-F_{\al}=\frac{{\theta}^g}{\al}-4-\frac{{\theta}^f}{\al}=\frac{{\theta}^g-{\theta}^f}{\al}-4>0 \imp e^{(G_{\al}-F_{\al})x}\ \mbox{increasing}\ \mbox{in}\ \left[ 0,\frac{1}{4} \right]
\]
moreover:
\[
\textstyle G_{F_{\al}} (0)=\frac{{\theta}^g}{{\theta}^f}>1\ \ \mbox{and}\ \ G_{F_{\al}} \left (\frac{1}{4} \right) =0
\]
for the existence and uniqueness of the stationary point, we prove that $G_{F_{\al}}$ is decreasing in $\left [0,\frac{1}{4} \right]$.
\[
\textstyle G'_{F_{\al}} (x)= \frac{1}{F_{\al}}\left[-4G_{\al}\frac{4x-1}{(2x-1)^3}+8\frac{1-8x}{(2x-1)^4}\right]
\]
thus:
\begin{align*}
G'_{F_{\al}}(x)<0\ \quad \mbox{in}\ \left[ 0,\textstyle{\frac{1}{4}} \right] &~~ \textstyle \Longleftrightarrow ~~ \frac{1}{F_{\al}}\left[-4G_{\al}\frac{4x-1}{(2x-1)^3}+8\frac{1-8x}{(2x-1)^4}\right] <0\ && \textstyle \mbox{in}\ \left[ 0,\textstyle{\frac{1}{4}} \right] \\
&\textstyle ~~ \Longleftrightarrow ~~ 4G_{\al} \frac{4x-1}{(2x-1)^3} > 8\frac{1-8x}{2x-1}\ && \mbox{in}\ \left[ 0,\textstyle{\frac{1}{4}} \right] \\
&\textstyle ~~ \Longleftrightarrow ~~ G_{\al}(4x-1) > 2\frac{1-8x}{2x-1}\ && \mbox{in}\ \left[ 0,\textstyle{\frac{1}{4}} \right] \\
&~~ \Longleftrightarrow ~~ 8G_{\al}x^2 - 6G_{\al}x +G_{\al} -2 +16x >0 && \mbox{in}\ \left[ 0,\textstyle{\frac{1}{4}} \right].
\end{align*}
Given:
\[
Par(x)=8G_{\al}x^2 - 6G_{\al}x +G_{\al} -2 +16x,
\]
we have:
\[
\textstyle Par(0)=G_{\al}-2>2\ \mbox{for}\ \al \ \mbox{sufficiently small and}\ Par\left( \frac{1}{4} \right) =2
\]
and
\[
\textstyle Par'(x)=16G_{\al}x+16-6G_{\al}<0\ \mbox{in}\ \left[ 0,\frac{1}{4} \right]\ \mbox{for}\ \al \ \mbox{sufficiently small}.
\]
Therefore, $FG_{\al}$ has only one stationary point, which is a maximum. For the second derivative and the inflection point, the proof is similar.

As stated above, the case ${\theta}^f<0\ \et \ {\theta}^g <0$ is proven in a completely analogous way.

\smallskip

\paragraph{Subcase \boldmath $(f\mathord{>})$, unbounded and closed intervals:}

Lastly, we consider the case of unbounded intervals; more precisely, we deal with atoms of the form $(f>g)_{[v_r,+\infy[}$ with $v_r$ the greatest domain variable, being the opposite case $(f>g)_{]-\infty,v_1]}$ treatable in an analogous way. Observe that due to Step \ref{itemAlgoOne}.\ref{alg1:actionOne}), there are no more literals of the form $(f>g)_{]-\infty,v_1[}$ or $(f>g)_{]v_r,+\infty[}$. In this final subcase, we exploit the numeric variables $k^f_r$, and the related literals that have been introduced in Steps \ref{alg4:actionB:case2} and \ref{itemAlgoFour}.\ref{alg4:actH}) of the algorithm; since the only interval we explicitly treat is $[v_r, \infty[$, variables of type $y^f_r, t^f_r, \ga^f_r, k^f_r$ will be simply denoted by $y_f, t_f, \ga_f, k_f$. Furthermore, slightly deviating from previous notation, in this paragraph we adopt a tilde for the real value assigned to the variable, e.g. $\tilde{t}_f$ denotes the real value of the variable $t_f$ in the numeric model under consideration. (We briefly recall that $y_f$ and $t_f$ represent, respectively, the value and the derivative of (the function interpreting) $f$ in the last point $v_r$ of the domain variables.)

Our goal is to assign to any function variable $f$ which occurs in an atom of the form $(f>g)_{[v_r,+\infy[}$ a real parameter $\phi_f$ such that the following expression
\begin{equation}\label{eq:inf}\tag{**}
(Mf)({\eta}) \putAs \tilde{y}_f + (\tilde{t}_f -\phi_f)(1- e^{{\eta}_r -\eta }) + \phi_f (\eta - {\eta}_r)
\end{equation}
defines, over $[\eta_r, +\infty[$ , a function $(Mf)$ that complies simultaneously with order constraints, e.g $(f>g)_{[v_r,+\infy[}$, and derivative constraints, e.g. $(D[f]>y)_{[v_r,+\infy[}$; these latter literals will be treated in a later case.

With respect to \eqref{eq:inf}, the following computations hold:
\[
(Mf)(\eta_r)=\tilde{y}_f, \ (Mf)'(\eta_r)=\tilde{t}_f, \ \lim_{\eta \frec +\infty} (Mf)'(\eta )={\phi}_f
\]
in particular, $(Mf)$ has an oblique asymptote given by the straight line:
\[
r(\eta)={\phi}_f \eta + \tilde{y}_f +\tilde{t}_f - {\phi}_f \left( {\eta}_r +1 \right),\ \ \mbox{with}\ \ r ({\eta}_r)=\tilde{y}_f + \tilde{t}_f - {\phi}_f
\]
Let us define the following sets:\footnote{Observe that, differently from $\sK, \sF$ and $\Gamma$, the last set $\sM$ is a set of real numbers not variables.}
\begin{align*}
\sK & \putAs  \{ \mbox{set of all} \ k_f \ \mbox{occurring in}\ \phi_4 \} ,\\ 
\sF & \putAs  \{ \mbox{set of all function variables} \ f \ \mbox{such that} \ k_f \! \in \! \sK \} \\
\Gamma & \putAs  \{ \mbox{set of all} \ \ga_f \ \mbox{occurring in}\ \phi_4 \ \mbox{such that} \ f\! \in \! \sF  \} , \\ 
\sM & \putAs  \{ \tilde{\mu} \, | \, \ga_f \bowtie \mu \ \mbox{appears in}\ \phi_4 \ \mbox{with} \ {\bowtie}  \in \! \{ <, \leq, =, \geq , > \} \ \mbox{and} \ \ga_f \in \Gamma \} ,
\end{align*}
fixing also:%\Eu{}{Corrette?? le def. di\\ $m,M$ quando $\mathcal{M}=\emptyset$?}
\[
m \putAs \min \sM \ , \quad M \putAs \max \sM \ \quad \mbox{and} \ \quad m=M=0 \ \mbox{if} \ \sM=\emptyset.
\]
To each $f \! \in \! \sF$, we associate a bounded interval $I_f$ as follows: the ends points $\al_f$ and $\be_f$ of $I_f$ are defined as $\al_f \putAs \max \left(A_f \cup \{m-1\} \right)$ with $A_f \putAs \{ \tilde{\mu} \, | \, \ga_f \trianglerighteq \mu \ \mbox{appears in}\ \phi_4 \ \mbox{with} \ \trianglerighteq  \in \! \{ =, \geq , > \} \}$ and $\be_f \putAs \min \left( B_f \cup \{ M+1 \} \right)$ with $B_f \putAs \{ \tilde{\mu} \, | \, \ga_f \trianglelefteq \mu \ \mbox{appears in}\ \phi_4 \ \mbox{with} \ \trianglelefteq  \in \! \{ <, \leq, =,  \} \}$; moreover, if $\al_f = \tilde{\mu}_f$ with $\tilde{\mu}_f = \max A_f$ and $\ga_f > \mu_f$ appears in $\phi_4$, then $\al_f \notin I_f$, similarly for $\be_f$.

The interval $I_f$ represents the admissible values for $\phi_f$; for example, if $\ga_f \geq \mu_1$ and $\ga_f < \mu_2$ are the only literals involving $\ga_f$ that occur in $\phi_4$ with $\tilde{\mu}_1 = 2$ and $\tilde{\mu}_2 = 5$, then $\al_f =2$, $\be_f=5$ and $I_f = [2 , 5[$.

Finally, let $\sI$ be the set of all previously defined intervals $I_f$ with $f \! \in \! \sF$.

By partially ordering $\sI$ with $I_f \geq I_g$ iff $k_f \geq k_g$, we can apply \Lem{lem:intervals} to obtain a family $\left(\phi_f\right)_{f\in \sF}$ of real numbers such that
\[
\phi_f \in I_f \ \quad \mbox{and} \ \quad k_f \geq k_g \imp \phi_f \geq \phi_g.
\]
Unfortunately, this choice for the parameters $\left(\phi_f\right)_{f\in \sF}$ alone does not suffice to ensure the satisfaction of the constraints $(f > g)_{[v_r, +\infty[}$, it could be the case that $g>f$ in a right neighborhood of $\eta_r$; an example of such a phenomenon is given by the following formula
\[
\phi_4 \ \equiv \ y_f = 1 \, ~\et~ \, t_f=0 \, ~\et~ \, 0 \! \leq \! {\ga}_f \! < \! 3 \, ~\et~ \, y_g=0 \, ~\et~ \, t_g=3 \, ~\et~ \, 2 \! < \! {\ga}_g \! \leq \! 5 \, ~\et~ \,  k_f \! \geq k_g \, ~\et~ \, v_r=0,  
\]
applying \eqref{eq:inf} and \Lem{lem:intervals} to these numeric constraints leads to the following functions over $[0, +\infty[$
\begin{align*}
(Mf)(\eta) & =  \textstyle 1  -\frac{11}{4}(1- e^{ -\eta }) + \frac{11}{4} \eta,  \\
(Mg)(\eta) & =  \textstyle (3 -\frac{5}{2})(1- e^{ -\eta }) + \frac{5}{2} \eta,
\end{align*}
for which we have $(Mf)(1)=1 + \frac{11}{4}e^{-1} < 3 - \frac{1}{2}e^{-1}= (Mg)(1)$.

 To overcome this problem, we proceed as follows. If $\phi_f = \tilde{t}_f$, then from \eqref{eq:inf} $(Mf)$ is a straight line and we are done; let us consider the case $\phi_f < \tilde{t}_f$ (if $\phi_f > \tilde{t}_f$ the approach is completely analogous). First, a new interpolation point $\eta_{\infty} \putAs \eta_r +1$ is added. Secondly, for every function variable $f$ in $\sF$, let us denote by $\sF_{<f}$ and $\sF_{>f}$ the sets of function variables which are smaller, resp. greater, than $f$ with respect to the partial order given by variables $k$, for example $\sF_{<f}=\{ g \, | \, g \! \in \! \sF \ \mbox{and}\ k_f \geq k_g \}$. Thirdly, we fix $y^f_{inf} \putAs \max \{ \tilde{y}_g \, | \, g \! \in \! \sF_{<f} \}$ and $y^f_{sup} \putAs \min \{ \tilde{y}_g \, | \, g \! \in \! \sF_{>f} \}$ with $y^f_{inf} \putAs \tilde{y}_f -1$ and $y^f_{sup} \putAs \tilde{y}_f +1$ if $\sF_{<f}$, resp. $\sF_{>f}$, is empty; setting also $\underline{y_f} \putAs \frac{\tilde{y}_f + y^f_{inf}}{2}$ and $\overline{y_f} \putAs \frac{\tilde{y}_f + y^f_{sup}}{2}$. 

We now consider the straight lines $\overline{r_f}$, $r_f$ and $\underline{r_f}$ with angular coefficient $\phi_f$ passing, respectively, through the points $(\eta_r,\overline{y_f})$, $(\eta_r,\tilde{y}_f)$ and $(\eta_r,\underline{y_f})$; these lines define the new points $\overline{y^{\infty}_f} \putAs \overline{r_f}(\eta_{\infty})$, $y^{\infty}_f \putAs r_f(\eta_{\infty})$ and $\underline{y^{\infty}_f} \putAs \underline{r_f}(\eta_{\infty})$. Since we are considering the subcase $\phi_f < \tilde{t}_f$, and thus we search for a concave function in $[\eta_{\infty}, +\infty[$, let us fix $\widehat{y_f} \putAs \frac{y_f^{\infty} + \overline{y_f^{\infty}}}{2}$ and $ \widehat{t_f} \putAs \frac{\widehat{y_f} + \overline{y_f^{\infty}}}{2} + \phi_f - \widehat{y_f}$. Finally, over $[\eta_{\infty}, +\infty[$ we define the following function:
\[
(Mf)({\eta}) = \widehat{y_f} + (\widehat{t_f} -{\phi}_f )(1- e^{{\eta}_{\infty} -\eta }) + {\phi}_f (\eta - {\eta}_{\infty}),
\]
given our choice for the parameters $\widehat{y_f}$, $\widehat{t_f}$ and $\phi_f$ this function passes through the point $(\eta_{\infy},\widehat{y_f})$ and, after $\eta_{\infy}$, lies strictly between $\overline{r_f}$ and $\underline{r_f}$ (in this case actually between $\overline{r_f}$ and $r_f$). The following picture summarizes this method.

