    ------------
\end{center}



\noindent {\boldmath\large${\fhi}_3 \imp {\fhi}_4 )$}\ We need to demonstrate that if a model for ${\fhi}_3$ exists, then it is possible to construct a model that satisfies all the formulas introduced in ${\fhi}_4$.

Let $M$ be a concrete model for ${\fhi}_3$. Note that only the numerical variables $\ga$ and $k$, which were added during the transformation process, are not interpreted by $M$; moreover, observe that the majority of the clauses in $\phi_4$, where no numerical variable $\ga$ or $k$ appears, are direct consequences of $\phi_3$, and thus are already satisfied by $M$.

Now, let $ {\eta}_1 < {\eta}_2 < \dots < {\eta}_r $ denote the domain-variable interpretations in the model $M$.

\begin{definition}[Variables $\ga$] Fix two points ${\ep}_0 \in {]-\infty} , {\eta}_1 [$ and ${\ep}_r \in {]{\eta}_r} , +\infty [$, and, for each function variable $f \! \in \! F$, consider the real values
\[
\textstyle c_0^f \! \putAs \frac{{\bar{y}}_1^f - (Mf)({\ep}_0)}{{\eta}_1 - {\ep}_0}\ \ \mbox{and}  \ \ c_r^f \! \putAs \frac{(Mf)({\ep}_r) - {\bar{y}}_r^f}{{\ep}_r - {\eta}_r}.
\]
The model $M$ gets extended with the following interpretations of $\ga$s, where, for each function variables $f\! \in \! F$, we set
\[
{\bar{\ga}}_i^f = M({\ga}_i^f) = c_i^f,\ \ \ i\in \{ 0, r \} . \tag*{\eod}
\]
\end{definition}
\begin{definition}[Variables $k$] For each function variable $f\! \in \! F$, consider the following real values:
\[
 l_0^f \! \putAs
  \left\{
     \begin{array}{lll}
      1 & \mbox{if} & \liminf_{x \frec -\infty}(Mf)(x)=+\infty, \\
      \frac{2\:arctg(\tau)}{\pi} & \mbox{if} & \liminf_{x \frec -\infty}(Mf)(x)= \tau, \\
      -1 & \mbox{if} & \liminf_{x \frec -\infty}(Mf)(x)=-\infty;
     \end{array}
   \right. 
 \ \ 
l_r^f \! \putAs
  \left\{
     \begin{array}{lll}
      1 & \mbox{if} & \liminf_{x \frec +\infty}(Mf)(x)=+\infty, \\
      \frac{2\:arctg(\tau)}{\pi} & \mbox{if} & \liminf_{x \frec +\infty}(Mf)(x)= \tau, \\
      -1 & \mbox{if} & \liminf_{x \frec +\infty}(Mf)(x)=-\infty.
     \end{array}
   \right.   
\]
The model $M$  gets extended with the following interpretation of $k$'s, where, for each function variable $f \! \in \! F$, we set:
\[
{\bar{k}}_i^f = M({k}_i^f) = l_i^f,\ \ \ i\in \{ 0, r \} .\tag*{\eod}
\]
\end{definition}

To complete the proof, we need to confirm that all clauses in $\fhi_4$, introduced in step \ref{itemAlgoFour}), are satisfied, particularly those that involve the numerical variables $\ga$ and $k$.


\paragraph{Case \boldmath{$(f\mathord{=})$:}} 
Let $(f=g)_{[z_1 , z_2 ]}$ be a literal occurring in ${\fhi}_3$. The formulas introduced in step \ref{itemAlgoFour}.\ref{alg4:actA}) are trivially satisfied; in particular, if $z_1 = - \infty $, we have ${\bar{\ga}}_0^f = {\bar{\ga}}_0^g $, because $c_0^f = c_0^g $. The case $z_2 = +\infty$ is similar.


\paragraph{Case \boldmath{$(f\mathord{>})$:}} 
As previously, we begin by considering the closed case. Let $(f>g)_{[w_1 ,w_2 ]}$ represent a literal occurring in ${\fhi}_3$. It is straightforward to confirm that the corresponding formulas introduced in step \ref{itemAlgoFour}.\ref{alg4:actB}) are satisfied.


Let now $(f>g)_{]w_1 ,w_2 [}$ be a literal occurring in ${\fhi}_3$, we have:
\[
(Mf)(\eta) > (Mg)(\eta )\ \ \ \forall \eta \! \in ]{\eta}_{\mathit{ind}(w_1)} , {\eta}_{\mathit{ind}(w_2)}[.
\]
Thus, by the literal added in step \ref{itemAlgoThree}), we have:
\[
{\bar{y}}_i^f = (Mf)({\eta}_i) > (Mg)({\eta}_i) = {\bar{y}}_i^g
\]
for all $i$ such that $\ind(w_1)+1 \leq i \leq \ind(w_2)-1$. If $w_1 < w_2 $ as domain ordered variables, because of step \ref{itemAlgoOne}.\ref{alg1:actionOne}) of the algorithm we have:
\[
\begin{array}{c}
(Mf)({\eta}_{\mathit{ind}(w_1)})=(Mg)({\eta}_{\mathit{ind}(w_1)}),\\
(Mf)({\eta}_{\mathit{ind}(w_2)})=(Mg)({\eta}_{\mathit{ind}(w_2)}).
\end{array}
\]
Then, because of step \ref{itemAlgoOne}.\ref{alg1:actionThree}) and \Lem{lem:1.14}, we have:
\[
\begin{array}{c}
{\bar{t}}_{\mathit{ind}(w_1)}^f = (Mf)'({\eta}_{\mathit{ind}(w_1)}) \geq (Mg)'({\eta}_{\mathit{ind}(w_1)}) = {\bar{t}}_{\mathit{ind}(w_1)}^g ,\\
{\bar{t}}_{\mathit{ind}(w_2)}^f = (Mf)'({\eta}_{\mathit{ind}(w_2)}) \leq (Mg)'({\eta}_{\mathit{ind}(w_2)}) = {\bar{t}}_{\mathit{ind}(w_2)}^g .
\end{array}
\]
For literals of the types $(f>g)_{] w_1, w_2]}$ and $(f>g)_{[w_1 ,w_2 [}$, the proof is similar.

Finally, for unbounded literals, such as $(f \! > \! g)_{[w_1, +\infty[} $, if $(Mf)\! > \! (Mg)$ in $[w_1, +\infty[$, then $\liminf_{x \frec +\infty}(Mf)(x) \geq \liminf_{x \frec +\infty}(Mg)(x)$. Thus, $l_r^f \! \geq \! l_r^f$, and so $\bar{k}_r^f \! \geq \! \bar{k}_r^g $. Similarly, one can proceed in the case of literals of the types $(f>g)_{] -\infty, w_1]}$ and $(f>g)_{]-\infty , +\infty[}$.


\paragraph{Case \boldmath{$(D\mathord{\geq})$:}} 
Let $(D[f]\geq y )_{[z_1 ,z_2]}$ be a literal occurring in ${\fhi}_3$. The formulas introduced in step \ref{itemAlgoFour}.\ref{alg4:actC}) are satisfied. Trivially, we have $(Mf)'({\eta}_i)={\bar{t}}_i^f \geq \bar{y}$, for each $i \in \{ \ind(z_1), \dots , \ind(z_2)-1 \}$; while satisfiability of formulas $\frac{y_{j+1}^f -y_j^f}{v_{j+1} -v_j} \geq y$, for each $j\in \{ \ind(z_1), \dots , \ind(z_2)-1 \}$, can easily be checked as follows. In each interval $[{\eta}_j , {\eta}_{j+1} ] \subset [Mz_1, Mz_2 ]$, the function $(Mf)$ is continuous and differentiable and we can apply the mean value theorem; that is, $\exists \ep \in ]{\eta}_j , {\eta}_{j+1}[$ such that
\[
\textstyle \dfrac{(Mf)({\eta}_{j+1})-(Mf)({\eta}_j)}{{\eta}_{j+1} -{\eta}_j}=(Mf)'(\ep ).
\]
The satisfiability of formulas follows from the hypothesis $(Mf)'(x)\geq \bar{y}$ for each $x \in [Mz_1, Mz_2]$.\\
Moreover, if $\frac{{\bar{y}}_{j+1}^f -{\bar{y}}_j^f}{{\eta}_{j+1} - {\eta}_j}= {\bar{t}}_{j+1}^f = \bar{y}$ we have $(Mf)'({\eta}_j)=(Mf)'({\eta}_{j+1}) = \bar{y}$ by \Lem{lem:1.11}, that is, $ {\bar{t}}_j^f = {\bar{t}}_{j+1}^f = \bar{y}$.

If $z_1= -\infty $, we have ${\bar{\ga}}_0^f = c_0^f \geq \bar{y}$ because of the mean value theorem; the case $z_2= +\infty$ can be treated analogously.

Let $(D[f]>y)_{]w_1 w_2[}$ be a literal occurring in ${\fhi}_3$, we have:
\[
(Mf)'(\eta )> \bar{y} \ \ \ \forall \eta \in ]{\eta}_{\mathit{ind}(w_1)}, {\eta}_{\mathit{ind}(w_2)}[.
\]
Thus, because of the formulas introduced in step \ref{itemAlgoThree}), we have:
\[
{\bar{t}}_i^f =(Mf)'(\eta ) > \bar{y}
\]
for all $i$ such that $ \ind(w_1) \! < \! i \! < \! \ind(w_2) $. Moreover, if ${\eta}_h$ and ${\eta}_{h+1}$ are two consecutive domain variables, because of the mean value theorem it exists $\ep \in ]{\eta}_h , {\eta}_{h+1}[$ such that:
\[
\textstyle \dfrac{(Mf)({\eta}_{h+1}) -(Mf)({\eta}_h)}{{\eta}_{h+1} - {\eta}_h }= (Mf)'(\ep ).
\]
Then, because of step \ref{itemAlgoThree}) of the algorithm, we have:
\[
\frac{{\bar{y}}_{j+1}^f - {\bar{y}}_j^f}{{\eta}_{j+1}-{\eta}_j} =\frac{(Mf)({\eta}_{j+1}) - (Mf)({\eta}_j)}{{\eta}_{j+1} - {\eta}_j } > \bar{y}
\]
for all $j$ such that $\ind(w_1) \! \leq \! j \! \leq \! \ind(w_2)-1$.

The satisfiability of the other literals, $(D[f]\bowtie y)_{[z_1, z_2]}$, $(D[f]\bowtie y)_{]w_1, w_2]}$ and $(D[f]\bowtie y)_{[w_1, w_2[}$ with ${\bowtie} \in \{=, >, <,\\\leq \}$, is again verified in a similar manner.


\paragraph{Case \textbf{(Mon):}} 
Let Strict$\_$Up$(f)_{[z_1 ,z_2]}$ (resp. Strict$\_$Down$(f)_{[z_1 ,z_2]}$) be a literal occurring in ${\fhi}_3$, it is immediate to verify that the corresponding formulas introduced in step \ref{itemAlgoFour}.\ref{alg4:actE}) are satisfied. 


\paragraph{Case \textbf{(Con):}} 
Let Convex$(f)_{[z_1 ,z_2 ]}$ be a literal occurring in ${\fhi}_3$. Due to the convexity of the function $(Mf)$ in $[Mz_1 , Mz_2]$, the formulas introduced in step \ref{itemAlgoFour}.\ref{alg4:actF}) are satisfied, because in that interval $(Mf)$ does not lie below the straight line tangent to $(Mf)$ in any point $(x, (Mf)(x))$ for each $x\in [Mz_1 , Mz_2]$; e.g., for each $i \in \{ \ind(z_1), \dots, \ind(z_2)-1 \}$, the point $({\eta}_{i+1}, {\bar{y}}_{i+1}^f)$ does not lie below the straight line tangent to $(Mf)$ in $({\eta}_i , {\bar{y}}_{i+1}^f)$.

Moreover, if $\frac{{\bar{y}}_{i+1}^f - {\bar{y}}_i^f}{{\eta}_{i+1} - {\eta}_i }$ equals ${\bar{t}}_i^f$ or ${\bar{t}}_{i+1}^f$, we have $(Mf)'({\eta}_i)=(Mf)'({\eta}_{i+1})$ by \Lem{lem:1.12}, i.e., ${\bar{t}}_i^f = {\bar{t}}_{i+1}^f$.

Finally, in a completely analogous way, if $z_1 = -\infty$ (resp. $z_2 = +\infty$) we have ${\bar{\ga}}_0^f \leq {\bar{t}}_1^f$ (resp. ${\bar{\ga}}_r \geq {\bar{t}}_r^f$).

Likewise, one verifies that all literals of the forms Strict$\_$Concave$(f)_{[z_1 ,z_2]}$, Concave$(f)_{[z_1 ,z_2]}$, Strict$\_$Convex$(f)_{[z_1, z_2]}$ appearing in ${\fhi}_3$ are satisfied. 


We can now restate and prove our goal, namely:
\begin{theorem} The $RDF^+$ theory is decidable.
\end{theorem}
\dimostraz We have built up and proved the following chain of equisatisfiability
results:
\[\begin{array}{rcccl}
\fhi_{i-1} & \mbox{and} & \fhi_{i} & \mbox{are equisatisfiable,} &
 \mbox{for\ $i=1,2,3,4$}\:. \end{array}
\] 
Formula ${\fhi}_4$, which contains only numerical variables, the numerical operators $+,\x\, $, and the comparators $=,<$ between reals, is decidable using Tarski's decision method. \qed


\section{Related Work and Conclusions}\label{sec:final}

We now briefly consider several aspects of the topics discussed so far, with particular attention to complexity-related results and potential future developments.

\subsection{Related literature and complexity issues} \label{subsec:relatedWork} 

The decidability of the \RDFp theory, as outlined above, builds upon a series of earlier results concerning the \ita{RMCF}, \ita{$RMCF^+$}, and \ita{RDF} theories \cite{DC06,DC07,DC87,GC00}. A comprehensive overview of these findings is available in \cite{DC12}, which also discusses additional decidability results in real analysis, notably those related to the Friedman–Seress theory \cite{FS89,FS90}.  

Since the decidability of \RDFp is established via an explicit algorithm, assessing its computational complexity is both natural and necessary. Our procedure incorporates Tarski’s decision method and therefore inherits its complexity as a lower bound. The first substantial improvement over Tarski's original approach was introduced by Collins \cite{GC 75}, whose cylindric algebraic decomposition (CAD) method has doubly exponential complexity in the number of variables (or exponential, if the number of variables is fixed). 
This technique also found applications in problems such as the \ita{Piano Movers} problem \cite{SS 83}. 

Grigoriev further refined Collins' method by devising an algorithm tailored for sentences in prenex normal form, exhibiting doubly exponential complexity with respect to the number of quantifier alternations~\cite{DG 88}. In the specific context of the \ita{existential} theory of reals, known decision procedures generally have exponential complexity in the number of variables~\cite{BasuPR96}. However, if the number of variables is fixed, the complexity drops to polynomial-time~\cite{JR 88}.

Lastly, while Tarski proved the undecidability of the elementary algebra \EAR of the real numbers when extended with certain transcendental functions such as $\sin x$~\cite{AT 51}, Richardson later showed that even the existential theory becomes undecidable when it includes the constants $\log 2$, $\pi$, and the functions $e^x$ and $\sin x$~\cite{DR 68}.


\subsection{Conclusions and follow-up work} \label{subsec:Conclusion}

This article has presented a decision algorithm for a fragment of real analysis, called \RDFp, which extends \EAR with variables designating real-valued functions possessing continuous derivatives. We began by introducing the syntax and semantics of \RDFp, illustrating how to define derived relators and express common analytic properties and classical theorems within the theory. We then described in full detail the reduction algorithm, which transforms a generic \RDFp formula $\fhi$ into an equisatisfiable \EAR formula $\widehat{\fhi}$ through four successive steps that eliminate function variables. A concrete example followed to demonstrate the algorithm in practice.

The correctness of the decision procedure---specifically, the equisatisfiability of $\fhi$ and $\widehat{\fhi}$---relies on the construction of suitable functional models. These models are obtained from a particular class of functions, the so-called $[\al, {\theta}_1, {\theta}_2]$-defined functions, introduced to meet the needs of the completeness proof.

The present article reorganizes and fills in gaps left by previous published work \cite{BCCOS20,DC07} as well as by earlier unpublished notes. The framework developed here has since been extended in a series of follow-up papers. In particular, \cite{BCCOS23} introduces a new theory, \RDFs, which enriches \RDFp with two functional term operators: function addition and scalar multiplication. Specifically, if $f,g$ are function terms, then $f+g$ denotes their pointwise sum, and if $s$ is a numerical term, then $s \x f$ denotes the pointwise product of $s$ and $f$. These operators permit more expressive atoms---e.g., $(f+g = h)_A$ and $(D[s \x f] > t)_A$---necessitating a refinement of the decision algorithm and a new class of interpolating functions for the completeness proof.

A further extension is proposed in \cite{BCCOS24}, where a family of theories \RDFn (with $n \! \in \! \mN$) is introduced. For each fixed $n$, the syntax of \RDFn extends that of \RDFs by adding derivative operators $D^{\al}[\cdot]$ for each $1 \leq \al \leq n$. These operators enable reasoning about functions of class $C^n$, thus broadening the expressivity beyond merely continuously differentiable ($C^1$) functions.

Future directions include further expansions of the syntax---for example, the addition of function product operators or the generalization of the theory to multivariate functions. In the latter case, the standard semantics would shift from unary functions $\mR \to \mR$ to multivariate functions $\mR^n \to \mR^m$, a change that seems well-supported by the current structure of the algorithm. Lastly, although Tarski established the undecidability of \EAR when extended with certain transcendental functions, a deeper investigation into the boundaries of undecidability for such extensions remains an open and relevant research avenue. A preliminary exploration in this direction is presented in \cite{BCCOS24}.

